window.EyeParts=window.EyeParts||{};window.EyeParts.addFirstTimeIntros=function addFirstTimeIntros(ed){Object.assign(ed,{showTabIntro});const TAB_INTROS={overview:{title:`Overview`,text:`this is your at-a-glance page. the Today card at the top shows only what needs you now, then comes your next shoot and everything after it, with small flags for what each shoot still needs. tap NEW SHOOT on Shoots anytime to start a new one.`},shoots:{title:`Shoots`,text:`every active shoot lives here, grouped by status from early idea through delivered. Filter by category up top, and tap any card to reopen it.`},archive:{title:`Archive`,text:`shoots move here once you mark them complete, keeping your active list clean while still letting you look back. This is also where you'll find backup and restore for all your data.`},journal2:{title:`Reflections`,text:`one running page with two kinds of entries. The weekly log fills itself in for every week you shoot: which shoots happened, their categories, and the lessons learned pulled from each shoot's reflection. Tap any shoot or takeaway to see where it came from. Tap '+' to add your own reflection anytime, and tag entries with hashtags so you can find them again later. The table of contents jumps you to any entry or week.`},stats:{title:`Stats`,text:`swipe between breakdowns of your visual languages, categories, team members, statuses, and locations. tap any slice to see exactly which shoots are behind it.`}};const TAB_INTRO_KEY=`dailies_seen_tab_intros_v1`;function loadSeenTabIntros(){try{return JSON.parse(localStorage.getItem(TAB_INTRO_KEY))||{}}catch(e){return{}}}let seenTabIntros=loadSeenTabIntros();function showTabIntro(view){const intro=TAB_INTROS[view];if(!intro||seenTabIntros[view])return;document.getElementById(`tabIntroTitle`).textContent=intro.title;document.getElementById(`tabIntroText`).textContent=intro.text;document.getElementById(`tabIntroOverlay`).hidden=false;seenTabIntros[view]=true;localStorage.setItem(TAB_INTRO_KEY,JSON.stringify(seenTabIntros))}document.getElementById(`tabIntroCloseBtn`).addEventListener(`click`,()=>{document.getElementById(`tabIntroOverlay`).hidden=true})};
