window.EyeParts=window.EyeParts||{};window.EyeParts.addProjectsProjectPopup=function addProjectsProjectPopup(ed){Object.assign(ed,{openProjectPopup,refreshOpenProjectPopup,closeProjectPopup});let activeProjectId=null;let projectPopupHideTimer=null;let projectPopupBusy=false;function renderProjectPopupBody(project){const members=ed.projectMembers(project.id);document.getElementById(`projectDetailTitle`).textContent=project.name;const n=members.length;document.getElementById(`projectDetailSummary`).textContent=[`${n} shoot${n===1?``:`s`}`,ed.projectDateRangeText(members.filter(ed.isProjectLiveShoot)),ed.projectStatusLabel(members)].filter(Boolean).join(` · `);document.getElementById(`projectArchiveBtn`).textContent=members.length&&members.every(s=>s.archived)?`Unarchive project`:`Archive project`;const list=document.getElementById(`projectDetailList`);list.innerHTML=``;members.forEach(s=>{ed.renderCompactShootRow(list,s);const info=ed.projectDayInfo(s);if(!info)return;const titleEl=list.lastElementChild&&list.lastElementChild.querySelector(`.shoot-row-compact-title`);if(titleEl)titleEl.textContent=`Day ${info.day} · ${titleEl.textContent}`})}function hideProjectRename(){document.getElementById(`projectRenameRow`).hidden=true}function openProjectPopup(projectId){const project=ed.findProject(projectId);if(!project||!ed.projectMembers(project.id).length)return;const wasOpen=activeProjectId!==null;if(activeProjectId!==projectId)hideProjectRename();activeProjectId=projectId;clearTimeout(projectPopupHideTimer);renderProjectPopupBody(project);const overlay=document.getElementById(`projectDetailOverlay`);overlay.hidden=false;if(wasOpen)return;overlay.querySelector(`.stat-box-detail-modal`).scrollTop=0;ed.lockBodyScroll();requestAnimationFrame(()=>requestAnimationFrame(()=>overlay.classList.add(`open`)))}function refreshOpenProjectPopup(){if(activeProjectId===null)return;const project=ed.findProject(activeProjectId);if(!project||!ed.projectMembers(project.id).length){closeProjectPopup();return}renderProjectPopupBody(project)}function closeProjectPopup(){if(activeProjectId===null)return;activeProjectId=null;hideProjectRename();const overlay=document.getElementById(`projectDetailOverlay`);overlay.classList.remove(`open`);ed.unlockBodyScroll();clearTimeout(projectPopupHideTimer);projectPopupHideTimer=setTimeout(()=>{overlay.hidden=true},200)}document.getElementById(`projectDetailCloseBtn`).addEventListener(`click`,closeProjectPopup);document.getElementById(`projectDetailOverlay`).addEventListener(`click`,e=>{if(e.target===e.currentTarget)closeProjectPopup()});document.getElementById(`projectAddDayBtn`).addEventListener(`click`,async()=>{const project=ed.findProject(activeProjectId);if(!project||projectPopupBusy)return;const members=ed.projectMembers(project.id);if(!members.length)return;const dated=members.filter(s=>ed.scheduledShootDate(s));const latest=dated.length?dated[dated.length-1]:members[members.length-1];let nextDate=``;if(ed.scheduledShootDate(latest)){const[y,m,d]=latest.date.split(`-`).map(Number);nextDate=ed.formatDate(new Date(y,m-1,d+1))}projectPopupBusy=true;try{const shoot=await ed.copyShootForProject(latest,`day`,{date:nextDate});const liveProject=ed.findProject(project.id);const lead=ed.projectLeadOf(liveProject);if(lead&&shoot.projectId===project.id){ed.applyLeadDetails(lead,shoot);await ed.mirrorLeadImages(liveProject,lead,{board:true,cover:true},[shoot]);shoot.followsLead=true;shoot.mirrorSig=ed.mirrorSignature(shoot)}ed.saveState();ed.renderAll();ed.refreshOpenStatBoxDetail();if(shoot.projectId){const info=ed.projectDayInfo(shoot);const dayNumber=info?info.day:ed.projectMembers(project.id).length;ed.showToast(`Day ${dayNumber} added to ${project.name}`)}else{ed.showToast(`${project.name} was ungrouped, so this was added as its own shoot`)}if(ed.shootModalOverlay.hidden)ed.openShootModal(shoot.id)}catch(err){ed.showToast(`Couldn't add a day. Please try again.`)}finally{projectPopupBusy=false}});document.getElementById(`projectRenameBtn`).addEventListener(`click`,()=>{const project=ed.findProject(activeProjectId);if(!project)return;const row=document.getElementById(`projectRenameRow`);if(!row.hidden){row.hidden=true;return}const input=document.getElementById(`projectRenameInput`);input.value=project.name;row.hidden=false;input.focus()});function saveProjectRename(){const project=ed.findProject(activeProjectId);const name=document.getElementById(`projectRenameInput`).value.trim();hideProjectRename();if(!project||!name||name===project.name)return;ed.state.projects=ed.projectsList().map(p=>p.id===project.id?{...p,name}:p);ed.saveState();ed.renderAll();ed.refreshOpenStatBoxDetail()}document.getElementById(`saveProjectRenameBtn`).addEventListener(`click`,saveProjectRename);document.getElementById(`projectRenameInput`).addEventListener(`keydown`,e=>{if(e.key===`Enter`)saveProjectRename()});document.getElementById(`projectArchiveBtn`).addEventListener(`click`,async()=>{const project=ed.findProject(activeProjectId);if(!project||projectPopupBusy)return;const members=ed.projectMembers(project.id);if(!members.length)return;const unarchiving=members.every(s=>s.archived);const n=members.length;const who=n===1?`Its 1 shoot moves`:`All ${n} shoots move`;const ok=await ed.askConfirm(unarchiving?{title:`Unarchive ${project.name}?`,text:`${who} back to Shoots.`,confirmLabel:`Unarchive`,cancelLabel:`Keep archived`}:{title:`Archive ${project.name}?`,text:`${who} to Archive.`,confirmLabel:`Archive`,cancelLabel:`Keep in Shoots`});if(!ok||activeProjectId!==project.id||!ed.findProject(project.id)||projectPopupBusy)return;ed.state.shoots=ed.state.shoots.map(s=>s.projectId===project.id?{...s,archived:!unarchiving}:s);ed.saveState();ed.renderAll();ed.refreshOpenStatBoxDetail();ed.showToast(unarchiving?`${project.name} is back in Shoots`:`${project.name} moved to Archive`)});document.getElementById(`projectUngroupBtn`).addEventListener(`click`,async()=>{const project=ed.findProject(activeProjectId);if(!project||projectPopupBusy)return;const n=ed.projectMembers(project.id).length;const rest=n===1?`Its 1 shoot stays as a separate shoot.`:`Its ${n} shoots stay as separate shoots.`;const ok=await ed.askConfirm({title:`Ungroup ${project.name}?`,text:rest,confirmLabel:`Ungroup`,cancelLabel:`Keep together`});if(!ok||activeProjectId!==project.id||!ed.findProject(project.id)||projectPopupBusy)return;const members=ed.projectMembers(project.id);members.forEach(s=>ed.setShootProject(s.id,``));ed.state.projects=ed.projectsList().filter(p=>p.id!==project.id);ed.saveState();closeProjectPopup();ed.renderAll();ed.refreshOpenStatBoxDetail()})};
