window.EyeParts=window.EyeParts||{};window.EyeParts.addOverviewDrawOverview=function addOverviewDrawOverview(ed){Object.assign(ed,{renderOverview});function renderOverview(){drawOverview();ed.repaginate(`overview`)}function setCount(id,n){document.getElementById(id).textContent=String(n)}function drawOverview(){ed.renderTodayCard();const byDate=(a,b)=>ed.dateTimeSortKey(a).localeCompare(ed.dateTimeSortKey(b));const comingShoots=ed.state.shoots.filter(s=>ed.isToday(s)||ed.isUpcoming(s)).sort(byDate);const next=comingShoots[0]||null;ed.renderNextShoot(next);const upcomingShoots=comingShoots.slice(1);const deadlineShoots=ed.state.shoots.filter(ed.isUpcomingDeadline).filter(s=>ed.weekBucket(s.deadline)===`this_week`||ed.weekBucket(s.deadline)===`next_week`).sort((a,b)=>ed.dateSortKey(a.deadline).localeCompare(ed.dateSortKey(b.deadline)));const proofsPendingShoots=ed.state.shoots.filter(s=>!s.archived&&s.status===`captured`&&!ed.isVideoShoot(s)).sort(byDate);const upcomingItems=ed.collapseProjects(upcomingShoots);const proofsPendingItems=ed.collapseProjects(proofsPendingShoots);const deadlineItems=ed.collapseProjects(deadlineShoots);document.getElementById(`upcomingSection`).hidden=!upcomingItems.length;setCount(`upcomingCount`,upcomingItems.length);const upList=document.getElementById(`upcomingShootsList`);upList.innerHTML=``;if(upcomingItems.length)ed.renderBucketedShoots(upList,upcomingItems,[`this_week`,`next_week`,`later`],`date`,{showStatus:true});document.getElementById(`proofsPendingSection`).hidden=!proofsPendingItems.length;setCount(`proofsPendingCount`,proofsPendingItems.length);const proofsList=document.getElementById(`proofsPendingShootsList`);proofsList.innerHTML=``;proofsPendingItems.forEach(item=>ed.renderListItem(proofsList,item,{showStatus:true}));document.getElementById(`upcomingDeadlinesSection`).hidden=!deadlineItems.length;setCount(`upcomingDeadlinesCount`,deadlineItems.length);const deadlineList=document.getElementById(`upcomingDeadlinesShootsList`);deadlineList.innerHTML=``;if(deadlineItems.length)ed.renderBucketedShoots(deadlineList,deadlineItems,[`this_week`,`next_week`],`deadline`,{showStatus:true,dueOnly:true})}};
