window.EyeParts=window.EyeParts||{};window.EyeParts.addOverviewTodayCard=function addOverviewTodayCard(ed){Object.assign(ed,{renderTodayCard});const SHOWN=2;const card=document.getElementById(`todayCard`);const items=document.getElementById(`todayCardItems`);const count=document.getElementById(`todayCount`);const more=document.getElementById(`todayMoreBtn`);const report=document.getElementById(`todayReportBtn`);const moreWords=document.getElementById(`todayMoreWords`);const moreDots=document.getElementById(`todayMoreDots`);function renderTodayCard(){const list=ed.todayItems();ed.tellShelf(list);const left=list.length-SHOWN;items.innerHTML=list.slice(0,SHOWN).map(ed.todayItemHtml).join(``);count.textContent=ed.todayCountWords(list.length);count.hidden=left<1;report.hidden=left>0;more.hidden=left<1;moreWords.textContent=ed.todayMoreWords(Math.max(left,0));moreDots.innerHTML=`<i></i>`.repeat(Math.min(Math.max(left,0),8));card.hidden=!list.length}items.addEventListener(`click`,e=>{const el=e.target.closest(`[data-act]`);if(el)ed.runTodayAct(el.dataset.act,el.dataset.id)});more.addEventListener(`click`,()=>ed.openNotificationsBell());report.addEventListener(`click`,()=>ed.openNotificationsBell())};
