window.EyeParts=window.EyeParts||{};window.EyeParts.addJournalList=function addJournalList(ed){Object.assign(ed,{journalFeedItems,renderJournal});function sortJournalEntriesRecent(entries){return entries.map((e,i)=>[e,i]).sort(([ea,ia],[eb,ib])=>{const cmp=(eb.createdAt||``).localeCompare(ea.createdAt||``);return cmp!==0?cmp:ib-ia}).map(([e])=>e)}ed.journalFilter=`all`;const JOURNAL_FILTERS=[{key:`all`,label:`All`},{key:`log`,label:`Weekly log`},{key:`entries`,label:`My entries`}];ed.JOURNAL_FILTERS=JOURNAL_FILTERS;function renderJournalFilterChips(){document.getElementById(`journalFilters`).innerHTML=JOURNAL_FILTERS.map(f=>`<button type="button" class="chip ${f.key===ed.journalFilter?`active`:``}" data-filter="${f.key}">${f.label}</button>`).join(``);document.getElementById(`journalFilterToggle`).innerHTML=`<span class="jt-word">Filter: </span>${ed.escapeHtml(JOURNAL_FILTERS.find(f=>f.key===ed.journalFilter).label)}`;document.getElementById(`journalFilterToggle`).style.display=ed.state.journalEntries.length?``:`none`}document.getElementById(`journalFilterToggle`).addEventListener(`click`,()=>{const filters=document.getElementById(`journalFilters`);filters.hidden=!filters.hidden});document.getElementById(`journalFilters`).addEventListener(`click`,e=>{const chip=e.target.closest(`.chip`);if(!chip||!chip.dataset.filter)return;ed.journalFilter=chip.dataset.filter;document.getElementById(`journalFilters`).hidden=true;renderJournal()});function journalFeedItems(){const entries=ed.journalFilter===`log`?[]:sortJournalEntriesRecent(ed.state.journalEntries).map(e=>({type:`entry`,date:e.createdAt||``,entry:e}));const weeks=ed.journalFilter===`entries`?[]:ed.computeWeeklyLog().map(w=>({type:`week`,date:ed.formatDate(w.start),week:w}));const merged=[];let i=0;let j=0;while(i<entries.length||j<weeks.length){if(j>=weeks.length||i<entries.length&&entries[i].date>=weeks[j].date)merged.push(entries[i++]);else merged.push(weeks[j++])}return merged}function renderJournal(){const photos=drawJournal();ed.repaginate(`journal`);return photos.then(done=>{ed.repaginate(`journal`);return done})}function drawJournal(){const items=journalFeedItems();const list=document.getElementById(`journalList`);list.innerHTML=``;renderJournalFilterChips();const empty=document.getElementById(`journalEmpty`);empty.hidden=items.length!==0;if(!empty.hidden){empty.textContent=ed.journalFilter===`log`?`No weekly log yet. It fills in on its own once a shoot is marked captured.`:ed.journalFilter===`entries`?`No entries of your own yet. Tap + to write one. Anything on your mind?`:`No weekly log yet. It fills in on its own once a shoot is marked captured.`}const weeks=new Map;const undated=[];items.forEach(item=>{if(!item.date){undated.push(item.entry);return}const start=ed.shootWeekWindow(item.date).start;const key=ed.formatDate(start);if(!weeks.has(key))weeks.set(key,{start,week:null,entries:[]});if(item.type===`week`)weeks.get(key).week=item.week;else weeks.get(key).entries.push(item.entry)});const imagePromises=[...weeks.values()].map(w=>ed.renderWeekCard(list,w.start,w.week,w.entries));if(undated.length)imagePromises.push(ed.renderWeekCard(list,null,null,undated));return Promise.all(imagePromises)}};
;

