window.EyeParts=window.EyeParts||{};window.EyeParts.addJournalContents=function addJournalContents(ed){function renderJournalTocItem(container,item){const row=document.createElement(`button`);row.type=`button`;row.className=`journal-toc-item`+(item.type===`week`?` journal-toc-item-log`:``);row.textContent=item.type===`week`?item.week.label:item.entry.title||`Untitled entry`;row.addEventListener(`click`,()=>scrollToJournalItem(item));container.appendChild(row)}function openJournalToc(){const items=ed.journalFeedItems();const list=document.getElementById(`journalTocList`);list.innerHTML=``;document.getElementById(`journalTocEmpty`).hidden=items.length!==0;ed.renderYearMonthGroups(list,items,{dateOf:item=>item.date,keyPrefix:`journalToc`,renderItem:renderJournalTocItem});document.getElementById(`journalTocOverlay`).hidden=false}document.getElementById(`journalTocBtn`).addEventListener(`click`,openJournalToc);function scrollToJournalItem(item){document.getElementById(`journalTocOverlay`).hidden=true;const selector=item.type===`week`?`.log-card[data-week-key="${item.date}"]`:`.journal-entry-card[data-entry-id="${item.entry.id}"]`;ed.renderJournal().then(()=>{const card=document.querySelector(selector);if(!card)return;const top=card.getBoundingClientRect().top+window.scrollY-parseFloat(getComputedStyle(document.getElementById(`app`)).paddingTop);window.scrollTo({top:Math.max(0,top),behavior:ed.motionOk()?`smooth`:`auto`})})}};
