// ---- pages/journal/weekly-log.js ----
window.EyeParts=window.EyeParts||{};window.EyeParts.addJournalWeeklyLog=function addJournalWeeklyLog(ed){Object.assign(ed,{shootWeekWindow,weekRangeLabel,computeWeeklyLog,logTakeaways,showLogShootRef,openLogShoot,logShootRowsHtml,wireLogShootRefs,renderWeekCard});function shootWeekWindow(dateStr){const[y,m,d]=dateStr.split(`-`).map(Number);const date=new Date(y,m-1,d);const start=new Date(date);start.setDate(date.getDate()-ed.daysIntoWeek(date));const end=new Date(start);end.setDate(start.getDate()+6);return{start,end}}function weekRangeLabel(start,end){return ed.rowDateRange(ed.formatDate(start),ed.formatDate(end),ed.todayStr())}function computeWeeklyLog(){const shotShoots=ed.state.shoots.filter(s=>s.date&&ed.POST_CAPTURE_STATUSES.includes(s.status));const weeks=new Map;shotShoots.forEach(s=>{const{start,end}=shootWeekWindow(s.date);const key=ed.formatDate(start);if(!weeks.has(key))weeks.set(key,{start,end,shoots:[]});weeks.get(key).shoots.push(s)});return Array.from(weeks.values()).sort((a,b)=>b.start-a.start).map(w=>({start:w.start,label:weekRangeLabel(w.start,w.end),shoots:w.shoots.slice().sort((a,b)=>a.date.localeCompare(b.date)),takeaways:logTakeaways(w.shoots)}))}function logTakeaways(shoots){return shoots.map(s=>({text:(s.lessonsLearned||``).replace(/\s*\n+\s*/g,` `).trim(),shootId:s.id})).filter(t=>t.text)}let logShootRefId=null;function showLogShootRef(shootId){const s=ed.state.shoots.find(x=>x.id===shootId);if(!s)return;logShootRefId=shootId;document.getElementById(`logShootRefName`).textContent=ed.shootDisplayName(s);document.getElementById(`logShootRefOverlay`).hidden=false}document.getElementById(`logShootRefCancelBtn`).addEventListener(`click`,()=>{document.getElementById(`logShootRefOverlay`).hidden=true});document.getElementById(`logShootRefViewBtn`).addEventListener(`click`,()=>{document.getElementById(`logShootRefOverlay`).hidden=true;if(logShootRefId)openLogShoot(logShootRefId)});function openLogShoot(shootId){const s=ed.state.shoots.find(x=>x.id===shootId);if(!s)return;ed.leaveMondayBrief();document.querySelector(`.tab[data-view="${s.archived?`archive`:`shoots`}"]`).click();ed.openShootModal(shootId);ed.showPostShootContentExpanded();ed.showShootPage(`postShootHeading`);ed.updateShootModalTitleFromScroll()}document.getElementById(`logShootRefOverlay`).addEventListener(`click`,e=>{if(e.target===e.currentTarget)e.currentTarget.hidden=true});const CHEVRON=`<svg viewBox="0 0 24 24" width="12" height="12" aria-hidden="true"><polyline points="9 5 16 12 9 19"/></svg>`;const plural=(n,one,many)=>`${n} ${n===1?one:many}`;function logShootRowsHtml(w){const today=ed.todayStr();return w.shoots.map(s=>{const lesson=(s.lessonsLearned||``).replace(/\s*\n+\s*/g,` `).trim();return`
        <div class="log-shoot-row">
          <span class="log-thumb">${ed.shootThumbHtml(s)}</span>
          <div class="log-shoot-body">
            <span class="log-label">${ed.escapeHtml(ed.metaLine([ed.shootDisplayName(s),ed.rowDate(s.date,today,false)]))}</span>
            <span class="log-lesson${lesson?``:` log-lesson-none`}">${ed.escapeHtml(lesson||`No lesson written yet.`)}</span>
            <button type="button" class="log-view-shoot" data-shoot-id="${ed.escapeHtml(s.id)}">View shoot ${CHEVRON}</button>
          </div>
        </div>`}).join(``)}function wireLogShootRefs(card){card.querySelectorAll(`.log-view-shoot[data-shoot-id]`).forEach(btn=>{btn.addEventListener(`click`,()=>openLogShoot(btn.dataset.shootId))})}function weekTitle(start,range){const thisWeek=shootWeekWindow(ed.todayStr()).start;const lastWeek=new Date(thisWeek);lastWeek.setDate(thisWeek.getDate()-7);const startStr=ed.formatDate(start);if(startStr===ed.formatDate(thisWeek))return`This week`;if(startStr===ed.formatDate(lastWeek))return`Last week`;return range}function renderWeekCard(container,start,week,entries){let range=``;if(start){const end=new Date(start);end.setDate(start.getDate()+6);range=weekRangeLabel(start,end)}const startStr=start?ed.formatDate(start):``;const title=start?weekTitle(start,range):`Undated`;const count=week?plural(week.shoots.length,`shoot`,`shoots`):plural(entries.length,`entry`,`entries`);const card=document.createElement(`div`);card.className=`card log-card`;if(week)card.dataset.weekKey=startStr;card.innerHTML=`
      <div class="log-week-head"><h3 class="log-week-heading">${ed.escapeHtml(title)}</h3><span class="log-week-meta">${ed.escapeHtml(range&&title!==range?range:count)}</span></div>
      ${week?logShootRowsHtml(week):``}`;wireLogShootRefs(card);container.appendChild(card);return Promise.all(entries.map(e=>ed.renderJournalEntryCard(card,e)))}};
;

