window.EyeParts=window.EyeParts||{};window.EyeParts.addJournalEntryPage=function addJournalEntryPage(ed){Object.assign(ed,{clearOpenJournalMarker,openJournalModal,closeJournalModal});const journalModalOverlay=document.getElementById(`journalModalOverlay`);ed.journalModalOverlay=journalModalOverlay;const OPEN_JOURNAL_KEY=`dailies_open_journal_entry`;ed.OPEN_JOURNAL_KEY=OPEN_JOURNAL_KEY;function setOpenJournalMarker(id){try{localStorage.setItem(OPEN_JOURNAL_KEY,id)}catch(e){}}function clearOpenJournalMarker(){try{localStorage.removeItem(OPEN_JOURNAL_KEY)}catch(e){}}function showJournalEditMode(){ed.journalMode=`edit`;document.getElementById(`journalSubject`).value=ed.currentJournalEntry.title;document.getElementById(`journalBody`).value=ed.currentJournalEntry.body;ed.currentJournalTags=[...ed.currentJournalEntry.tags];ed.renderJournalTagsChips();ed.renderJournalTagsSuggestions();ed.journalTagsInput.value=``;document.getElementById(`deleteJournalBtn`).hidden=ed.journalIsNew;ed.renderJournalImages();document.getElementById(`journalViewMode`).hidden=true;document.getElementById(`journalForm`).hidden=false}function showJournalViewMode(){ed.journalMode=`view`;const e=ed.currentJournalEntry;document.getElementById(`journalViewTitle`).textContent=e.title||`Untitled entry`;document.getElementById(`journalViewDate`).textContent=ed.prettyDate(e.createdAt);const tagsEl=document.getElementById(`journalViewTags`);tagsEl.innerHTML=(e.tags||[]).map(t=>`<span class="beat-chip view-only">${ed.escapeHtml(t)}</span>`).join(``);tagsEl.hidden=!(e.tags&&e.tags.length);document.getElementById(`journalViewBody`).textContent=e.body||``;document.getElementById(`journalViewLinkedHint`).hidden=!e.sourceShootId;document.getElementById(`deleteJournalViewBtn`).hidden=ed.journalIsNew;document.getElementById(`journalViewDoneBtn`).textContent=ed.pickRandomSaveMessage();ed.renderJournalViewImages();document.getElementById(`journalForm`).hidden=true;document.getElementById(`journalViewMode`).hidden=false}function openJournalModal(id,mode){const existing=id?ed.state.journalEntries.find(x=>x.id===id):null;ed.journalIsNew=!existing;ed.currentJournalEntry=existing||{id:ed.uid(),title:``,body:``,tags:[],createdAt:ed.todayStr()};setOpenJournalMarker(ed.currentJournalEntry.id);ed.journalHasImages=false;if(ed.journalIsNew||mode===`edit`&&!ed.currentJournalEntry.sourceShootId)showJournalEditMode();else showJournalViewMode();journalModalOverlay.hidden=false}async function revisitLinkedJournalEntry(){const entry=ed.currentJournalEntry;const shootId=entry.sourceShootId;const ok=await ed.askConfirm({title:`Revisit this shoot?`,text:`This entry is written from the shoot's reflection, so that's where it's changed.`,confirmLabel:`Go to shoot`,cancelLabel:`Stay here`});if(!ok||ed.currentJournalEntry!==entry)return;closeJournalModal();ed.openPostShootJournalPrompt(shootId)}document.getElementById(`journalViewBody`).addEventListener(`click`,()=>{if(ed.currentJournalEntry&&ed.currentJournalEntry.sourceShootId)revisitLinkedJournalEntry()});document.getElementById(`editJournalBtn`).addEventListener(`click`,()=>{if(ed.currentJournalEntry&&ed.currentJournalEntry.sourceShootId)revisitLinkedJournalEntry();else showJournalEditMode()});function closeJournalModal(){clearTimeout(ed.journalSaveTimer);ed.autosaveJournal();clearOpenJournalMarker();journalModalOverlay.hidden=true;ed.currentJournalEntry=null;ed.renderJournal()}document.getElementById(`addJournalBtn`).addEventListener(`click`,()=>openJournalModal(null));document.getElementById(`saveJournalBtn`).addEventListener(`click`,()=>{clearTimeout(ed.journalSaveTimer);ed.autosaveJournal();const e=ed.currentJournalEntry;const hasContent=e&&(ed.hasText(e.title)||ed.hasText(e.body)||e.tags.length>0||ed.journalHasImages);if(hasContent)showJournalViewMode();else closeJournalModal()});async function deleteCurrentJournalEntry(){const entry=ed.currentJournalEntry;if(!entry)return;if(!await ed.askDeleteJournalEntry()||ed.currentJournalEntry!==entry)return;if(!ed.currentJournalEntry.sourceShootId){ed.idbDeleteImages(ed.journalImagesKey(ed.currentJournalEntry.id)).catch(()=>{})}ed.state.journalEntries=ed.state.journalEntries.filter(x=>x.id!==ed.currentJournalEntry.id);ed.saveState();clearTimeout(ed.journalSaveTimer);clearOpenJournalMarker();journalModalOverlay.hidden=true;ed.currentJournalEntry=null;ed.renderJournal()}document.getElementById(`deleteJournalBtn`).addEventListener(`click`,deleteCurrentJournalEntry);document.getElementById(`deleteJournalViewBtn`).addEventListener(`click`,deleteCurrentJournalEntry);document.getElementById(`journalViewDoneBtn`).addEventListener(`click`,closeJournalModal);journalModalOverlay.addEventListener(`click`,e=>{if(e.target===journalModalOverlay)closeJournalModal()})};
;

