window.EyeParts=window.EyeParts||{};window.EyeParts.addShootFrameworkTags=function addShootFrameworkTags(ed){Object.assign(ed,{renderShootFrameworkTags,syncShootFrameworkTags});const FRAMEWORK_TAG_CONTAINER_IDS=[`frameworkTagsContainerEarly`,`frameworkTagsContainer`];ed.FRAMEWORK_TAG_CONTAINER_IDS=FRAMEWORK_TAG_CONTAINER_IDS;const FRAMEWORK_TAG_CHECKBOX_SELECTOR=FRAMEWORK_TAG_CONTAINER_IDS.map(id=>`#${id} input[type="checkbox"]`).join(`, `);const FRAMEWORK_TAG_CHECKED_SELECTOR=FRAMEWORK_TAG_CONTAINER_IDS.map(id=>`#${id} input[type="checkbox"]:checked`).join(`, `);ed.FRAMEWORK_TAG_CHECKED_SELECTOR=FRAMEWORK_TAG_CHECKED_SELECTOR;function renderFrameworkTagGroup(container,frameworks,selectedTags){container.innerHTML=frameworks.map(fw=>{return`
        <div class="framework-subsection">
          <h4 class="subsection-heading framework-heading" data-fw-id="${fw.id}">${ed.escapeHtml(fw.name)}</h4>
          <div class="framework-subsection-body" data-fw-body="${fw.id}">
            <div class="tag-group">
              ${fw.tags.map(tag=>{const entry=selectedTags.find(t=>t.frameworkId===fw.id&&t.tag===tag);return`<label class="tag-check"><input type="checkbox" data-fw="${fw.id}" value="${ed.escapeHtml(tag)}" ${entry?`checked`:``} /> ${ed.escapeHtml(tag)}</label>`}).join(``)}
            </div>
          </div>
        </div>
      `}).join(``)}function renderShootFrameworkTags(shoot){const earlyContainer=document.getElementById(`frameworkTagsContainerEarly`);const container=document.getElementById(`frameworkTagsContainer`);const selectedTags=shoot?shoot.frameworkTags||[]:[];const visualLanguageFws=ed.state.frameworks.filter(fw=>fw.name===`Visual Language`);const restFws=ed.state.frameworks.filter(fw=>fw.name!==`Visual Language`);renderFrameworkTagGroup(earlyContainer,visualLanguageFws,selectedTags);renderFrameworkTagGroup(container,restFws,selectedTags);container.hidden=restFws.length===0}function syncShootFrameworkTags(){if(!ed.shootModalOverlay.hidden){const s=ed.editingShootId?ed.state.shoots.find(x=>x.id===ed.editingShootId):null;renderShootFrameworkTags(s)}}FRAMEWORK_TAG_CONTAINER_IDS.forEach(id=>{document.getElementById(id).addEventListener(`change`,e=>{if(e.target.type!==`checkbox`||!e.target.checked)return;const all=[...document.querySelectorAll(FRAMEWORK_TAG_CHECKBOX_SELECTOR)];const next=all[all.indexOf(e.target)+1];if(next)next.focus()})})};
