window.EyeParts=window.EyeParts||{};window.EyeParts.addShootFields=function addShootFields(ed){Object.assign(ed,{autoSizeTextarea,autoSizeAllListTextareas,isBoxSheddingField,syncFieldFilledState,syncAllShootFormFields,shootListScroller,restoreAfterListReorder,restoreRemovedShootItem,followingAtRemoval});ed.currentShotList=[];function autoSizeTextarea(el){el.style.height=`auto`;if(!el.scrollHeight)return;const cs=getComputedStyle(el);const borders=parseFloat(cs.borderTopWidth)+parseFloat(cs.borderBottomWidth);el.style.height=el.scrollHeight+borders+`px`}function autoSizeAllListTextareas(){document.querySelectorAll(`#shotListItems .shot-text, #lightingSetupsItems .lighting-setup-description, #shootModeShotList .shot-text, #shootModeShootingNotes`).forEach(autoSizeTextarea)}function isBoxSheddingField(el){if(el.classList.contains(`shot-text`))return false;if(el.tagName===`TEXTAREA`)return true;return el.tagName===`INPUT`&&(!el.type||el.type===`text`)}function syncFieldFilledState(el){if(!el||!el.tagName||!isBoxSheddingField(el))return;const filled=!!el.value.trim();el.classList.toggle(`is-filled`,filled);if(el.tagName!==`TEXTAREA`)return;if(filled)autoSizeTextarea(el);else el.style.height=``}function syncAllShootFormFields(){document.querySelectorAll(`#shootForm input, #shootForm textarea`).forEach(syncFieldFilledState)}function shootListScroller(container){return container&&container.closest(`#shootWizardBody`)||ed.shootModalOverlay.querySelector(`.modal`)}function restoreAfterListReorder(container,checkIdx,savedScrollTop){const apply=()=>{const scroller=shootListScroller(container);if(scroller&&savedScrollTop!==undefined)scroller.scrollTop=savedScrollTop;if(checkIdx===undefined)return;const cb=container.querySelector(`.shot-check[data-idx="${checkIdx}"]`);if(cb)cb.focus({preventScroll:true})};apply();requestAnimationFrame(apply)}function restoreRemovedShootItem(shootId,listKey,idx,item,following){if(!ed.shootModalOverlay.hidden&&ed.currentShootId===shootId){const[list,render]={shotList:[ed.currentShotList,ed.renderShotList],lightingSetups:[ed.currentLightingSetups,ed.renderLightingSetups],teamMembers:[ed.currentTeamMembers,ed.renderTeamMembers]}[listKey];list.splice(Math.min(idx,list.length),0,item);render();ed.scheduleShootAutosave();if(following){ed.saveShootNow();reattachDayIfMatchingLead(shootId,following)}return}const openOtherId=!ed.shootModalOverlay.hidden&&ed.currentShootId?ed.currentShootId:null;if(openOtherId)ed.saveShootNow();const shoot=ed.state.shoots.find(s=>s.id===shootId);if(!shoot)return;if(!Array.isArray(shoot[listKey]))shoot[listKey]=[];shoot[listKey].splice(Math.min(idx,shoot[listKey].length),0,item);ed.saveState();if(following)reattachDayIfMatchingLead(shootId,following);const openDay=openOtherId&&(listKey===`lightingSetups`||listKey===`teamMembers`)?ed.state.shoots.find(s=>s.id===openOtherId):null;const openLead=openDay&&openDay.followsLead?ed.projectLeadOf(ed.findProject(openDay.projectId)):null;if(openLead&&openLead.id===shootId){const isSetups=listKey===`lightingSetups`;const working=isSetups?ed.currentLightingSetups:ed.currentTeamMembers;working.splice(Math.min(idx,working.length),0,isSetups?{...item,id:ed.uid()}:{...item});if(ed.mirrorSignature({...openDay,[listKey]:working})!==ed.mirrorSignature(openDay)){working.splice(0,working.length,...(openDay[listKey]||[]).map(x=>({...x})))}if(isSetups)ed.renderLightingSetups();else ed.renderTeamMembers();ed.scheduleShootAutosave()}if(listKey===`shotList`&&!ed.shootModeOverlay.hidden&&ed.getShootModeShootId()===shootId)ed.renderShootModeShots(shoot);ed.renderAll()}function followingAtRemoval(shootId){const s=ed.state.shoots.find(x=>x.id===shootId);return s&&s.followsLead&&s.projectId?{projectId:s.projectId,at:Date.now()}:null}function reattachDayIfMatchingLead(shootId,following){const day=ed.state.shoots.find(s=>s.id===shootId);if(!day||day.followsLead||day.projectId!==following.projectId)return;const lead=ed.projectLeadOf(ed.findProject(following.projectId));if(!lead||lead.id===day.id)return;if([day.id,lead.id].some(id=>(ed.shootImagesChangedAt.get(id)||0)>=following.at))return;const sig=ed.mirrorSignature(day);if(sig!==ed.mirrorSignature(lead))return;day.followsLead=true;day.mirrorSig=sig;ed.saveState();if(!ed.shootModalOverlay.hidden&&ed.currentShootId===day.id)ed.updateMultiDayRow()}};
