window.EyeParts=window.EyeParts||{};window.EyeParts.addConceptHelperHelperOutput=function addConceptHelperHelperOutput(ed){Object.assign(ed,{askHelperReplace});ed.CONCEPT_HELPER_OUTPUTS.forEach(out=>{document.getElementById(out.boxId).addEventListener(`input`,e=>{ed.autoSizeTextarea(e.target);ed.updateConceptHelperCount()})});function conceptHelperJoin(labels){return labels.length>1?`${labels.slice(0,-1).join(`, `)} and ${labels[labels.length-1]}`:labels[0]}function askHelperReplace(labels,fillsOthers){return ed.askConfirm({title:`Replace what's already in ${conceptHelperJoin(labels)}?`,text:fillsOthers?`Keep mine leaves what you wrote there and still fills in the rest.`:`Keep mine leaves what you wrote there.`,confirmLabel:`Replace`,cancelLabel:`Keep mine`,danger:true})}async function useConceptHelperOutputs(){const h=ed.conceptHelper;if(!h||h.asking)return;const picks=ed.conceptHelperShownOutputs().map(out=>({out,text:document.getElementById(out.boxId).value.trim(),field:document.getElementById(out.fieldId)})).filter(pick=>pick.text);if(!picks.length||picks.some(pick=>pick.text.length>ed.conceptHelperMax(pick.out)))return;const replacing=picks.filter(pick=>ed.hasText(pick.field.value)&&pick.field.value.trim()!==pick.text);let keepExisting=false;if(replacing.length){h.asking=true;keepExisting=!await askHelperReplace(replacing.map(pick=>pick.out.label),picks.length>replacing.length);h.asking=false;if(ed.conceptHelper!==h)return}picks.filter(pick=>!(keepExisting&&replacing.includes(pick))).forEach(({field,text})=>{field.value=text;field.dispatchEvent(new Event(`input`,{bubbles:true}));ed.syncFieldFilledState(field)});ed.closeConceptHelper()}document.getElementById(`conceptHelperUseBtn`).addEventListener(`click`,()=>{if(!ed.askConceptHelperLeave(`use`))useConceptHelperOutputs()});function writeConceptHelperOwn(){ed.closeConceptHelper();const premise=document.getElementById(`shootPremise`);if(premise.readOnly)ed.openExpandField(`shootPremise`);else premise.focus()}document.getElementById(`conceptHelperWriteBtn`).addEventListener(`click`,()=>{if(!ed.askConceptHelperLeave(`write`))writeConceptHelperOwn()});document.getElementById(`conceptHelperCloseBtn`).addEventListener(`click`,()=>{if(!ed.askConceptHelperLeave(`close`))ed.closeConceptHelper()});document.getElementById(`conceptHelperLeaveFirstBtn`).addEventListener(`click`,()=>{const h=ed.conceptHelper;if(!h)return;const target=ed.conceptHelperBlankIds()[0];if(target)ed.jumpConceptHelperTo(target);else{h.leaving=null;ed.renderConceptHelper()}});document.getElementById(`conceptHelperLeaveAnywayBtn`).addEventListener(`click`,()=>{const h=ed.conceptHelper;if(!h)return;const action=h.leaving;h.leaving=null;if(action===`write`)writeConceptHelperOwn();else if(action===`use`){ed.renderConceptHelper();useConceptHelperOutputs()}else ed.closeConceptHelper()})};
