window.EyeParts=window.EyeParts||{};window.EyeParts.addReflectionHelperHelper=function addReflectionHelperHelper(ed){Object.assign(ed,{openReflectHelper});const REFLECTION_FIELDS={right:{fieldId:`shootWentRight`,label:`What went right`},better:{fieldId:`shootCouldBeBetter`,label:`What could've gone better`},lessons:{fieldId:`shootLessonsLearned`,label:`Lessons for next time`}};const REFLECTION_FLOWS=window.EyeWords.reflectionFlows;ed.reflectHelper=null;const REFLECT_VOICE_TIP_KEY=`dailies_seen_reflect_voice_tip_v1`;function reflectFlowFor(category){return REFLECTION_FLOWS.find(f=>f.categories.includes(category))||REFLECTION_FLOWS.find(f=>f.categories.includes(``))||REFLECTION_FLOWS[0]}function storeReflectAnswer(){ed.reflectHelper.answers[ed.reflectHelper.index]=document.getElementById(`reflectHelperInput`).value.trim()}function wildCardReflectQuestions(){const shoot=ed.state.shoots.find(s=>s.id===ed.currentShootId);const cards=shoot&&Array.isArray(shoot.triedWildCards)?shoot.triedWildCards:[];const wentRight=document.getElementById(`shootWentRight`).value;return cards.map(card=>({card,plain:card.trim().replace(/[.…]+$/,``)})).filter(({plain})=>plain&&!wentRight.includes(plain)).slice(-3).map(({card,plain})=>({field:`right`,text:`You tried “${card.trim()}” Did it give you anything?`,placeholder:`e.g. the shot of her hands on the rail`,say:`From the wild card “${plain}”: {a}.`,sayYes:`The wild card “${plain}” paid off.`,lower:true}))}function renderReflectHelper(){const h=ed.reflectHelper;const questions=h.questions;const q=questions[h.index];const isLast=h.index===questions.length-1;document.getElementById(`reflectHelperStep`).textContent=`Question ${h.index+1} of ${questions.length}`;document.getElementById(`reflectHelperTitle`).textContent=REFLECTION_FIELDS[q.field].label;document.getElementById(`reflectHelperText`).textContent=q.text;const hint=document.getElementById(`reflectHelperHint`);hint.textContent=h.index===0?`Answer what you can. Anything you skip is just left out.`:``;if(h.index===0&&h.voiceTip){const tip=document.createElement(`span`);tip.className=`field-hint-bold`;tip.textContent=`Tip:`;hint.append(document.createElement(`br`),tip,` tap the mic on your keyboard and just talk.`)}hint.hidden=!hint.textContent;const input=document.getElementById(`reflectHelperInput`);input.placeholder=q.placeholder||``;input.value=h.answers[h.index]||``;document.getElementById(`reflectHelperBackBtn`).hidden=h.index===0;document.getElementById(`reflectHelperNextBtn`).textContent=isLast?`Finish`:`Next`}function goReflectHelper(step){const h=ed.reflectHelper;if(!h)return;storeReflectAnswer();const next=h.index+step;if(next>=h.questions.length){finishReflectHelper();return}h.index=Math.max(0,next);renderReflectHelper()}const REFLECTION_NOTHING=/^(no|nope|nah|none|nothing|nowhere|never|not really|not much|n\/?a|all good|it didn['’]?t|didn['’]?t)([\s,;:!.—–-]+(really|at all|all good|it didn['’]?t|nothing|it was fine|all fine|went fine))*$/i;function reflectSentence(q,answer){if(q.sayYes&&/^(yes|yeah|yep|yup|definitely|it did)[\s!.]*$/i.test((answer||``).trim()))return q.sayYes;let text=(answer||``).trim().replace(/[.!?…]+$/,``).replace(/^(yes|yeah|yep|yup|definitely)\b[\s,;:!.—–-]*/i,``);if(!text||ed.CONCEPT_HELPER_NONE.test(text)||REFLECTION_NOTHING.test(text))return``;let say=q.say;if(q.sayOwn){text=text.replace(/^(\.{2,}|…)\s*/,``).replace(/^next time[,:]?\s*/i,``);const withoutLeadIn=text.replace(/^(i['’]ll|i will)\s+/i,``);if(withoutLeadIn!==text&&withoutLeadIn)text=withoutLeadIn;else if(/^I(\s|['’])/.test(text))say=q.sayOwn;if(!text)return``}if(q.lower&&say===q.say&&/^[A-Z][a-z]/.test(text))text=text.charAt(0).toLowerCase()+text.slice(1);const sentence=say.replace(`{a}`,()=>text);return sentence.charAt(0).toUpperCase()+sentence.slice(1)}async function finishReflectHelper(){const h=ed.reflectHelper;if(!h||h.asking)return;storeReflectAnswer();const fills=Object.keys(REFLECTION_FIELDS).map(key=>{const field=document.getElementById(REFLECTION_FIELDS[key].fieldId);const text=h.questions.map((q,i)=>q.field===key?reflectSentence(q,h.answers[i]):``).filter(Boolean).join(` `).slice(0,field.maxLength>0?field.maxLength:1e3);return{key,field,text}}).filter(fill=>fill.text);const replacing=fills.filter(fill=>ed.hasText(fill.field.value)&&fill.field.value.trim()!==fill.text);let keepExisting=false;if(replacing.length){h.asking=true;keepExisting=!await ed.askHelperReplace(replacing.map(fill=>REFLECTION_FIELDS[fill.key].label),fills.length>replacing.length);h.asking=false;if(ed.reflectHelper!==h)return}fills.filter(fill=>!(keepExisting&&replacing.includes(fill))).forEach(({field,text})=>{field.value=text;field.dispatchEvent(new Event(`input`,{bubbles:true}));ed.syncFieldFilledState(field)});closeReflectHelper()}function openReflectHelper(){let voiceTip;try{voiceTip=localStorage.getItem(REFLECT_VOICE_TIP_KEY)!==`1`;if(voiceTip)localStorage.setItem(REFLECT_VOICE_TIP_KEY,`1`)}catch(err){voiceTip=false}const flow=reflectFlowFor(document.getElementById(`shootCategory`).value||``);const questions=[...flow.questions];const firstBetter=questions.findIndex(q=>q.field!==`right`);questions.splice(firstBetter===-1?questions.length:firstBetter,0,...wildCardReflectQuestions());ed.reflectHelper={flow,questions,index:0,answers:[],voiceTip};renderReflectHelper();document.getElementById(`reflectHelperOverlay`).hidden=false}function closeReflectHelper(){document.getElementById(`reflectHelperOverlay`).hidden=true;ed.queueShootBreak(250);const onClose=ed.reflectHelper&&ed.reflectHelper.onClose;ed.reflectHelper=null;if(onClose)onClose()}document.getElementById(`reflectHelperBtn`).addEventListener(`click`,openReflectHelper);document.getElementById(`reflectHelperBackBtn`).addEventListener(`click`,()=>goReflectHelper(-1));document.getElementById(`reflectHelperNextBtn`).addEventListener(`click`,()=>goReflectHelper(1));document.getElementById(`reflectHelperCloseBtn`).addEventListener(`click`,finishReflectHelper);document.getElementById(`reflectHelperInput`).addEventListener(`keydown`,e=>{if(e.key!==`Enter`||e.shiftKey||e.isComposing||e.keyCode===229)return;e.preventDefault();goReflectHelper(1)});document.getElementById(`shootWizardDontShowBtn`).addEventListener(`click`,()=>{ed.setNewShootGuideOn(false);ed.endShootWizard();document.getElementById(`shootWizardOffOverlay`).hidden=false});document.getElementById(`shootWizardOffOkBtn`).addEventListener(`click`,()=>{document.getElementById(`shootWizardOffOverlay`).hidden=true});ed.shootModalOverlay.querySelector(`.modal`).addEventListener(`animationend`,e=>{if(e.target===e.currentTarget&&ed.shootWizardPendingId)ed.startQueuedShootWizard()})};
