window.EyeParts=window.EyeParts||{};window.EyeParts.addProjectsPhotoCrop=function addProjectsPhotoCrop(ed){Object.assign(ed,{openProjectPhotoCrop});const cropOverlay=document.getElementById(`projectPhotoCropOverlay`);const cropStage=document.getElementById(`cropStage`);const cropImg=document.getElementById(`cropImg`);const cropZoomSlider=document.getElementById(`cropZoomSlider`);let cropBaseScale=1;let cropZoom=1;let cropOffsetX=0;let cropOffsetY=0;let cropStageWidth=0;let cropStageHeight=0;let cropDragging=false;let cropDragStartX=0;let cropDragStartY=0;let cropDragOffsetStartX=0;let cropDragOffsetStartY=0;const cropActivePointers=new Map;let cropPinchPrevDist=0;ed.cropTargetShootId=null;function clampCropOffsets(){const dispW=cropImg.naturalWidth*cropBaseScale*cropZoom;const dispH=cropImg.naturalHeight*cropBaseScale*cropZoom;const minX=Math.min(0,cropStageWidth-dispW);const minY=Math.min(0,cropStageHeight-dispH);cropOffsetX=Math.min(0,Math.max(minX,cropOffsetX));cropOffsetY=Math.min(0,Math.max(minY,cropOffsetY))}function applyCropTransform(){clampCropOffsets();cropImg.style.transform=`translate(${cropOffsetX}px, ${cropOffsetY}px) scale(${cropBaseScale*cropZoom})`}let cropMode=`project`;const CROP_OUTPUT={project:{width:192,height:240},talent:{width:240,height:300}};function openProjectPhotoCrop(src,mode){cropMode=mode===`talent`?`talent`:`project`;cropStage.classList.toggle(`crop-stage-talent`,cropMode===`talent`);document.getElementById(`cropModalTitle`).textContent=cropMode===`talent`?`Crop talent photo`:`Set cover photo`;cropZoom=1;cropZoomSlider.value=`1`;cropActivePointers.clear();cropDragging=false;cropImg.onload=()=>{const stageRect=cropStage.getBoundingClientRect();cropStageWidth=stageRect.width;cropStageHeight=stageRect.height;cropBaseScale=Math.max(cropStageWidth/cropImg.naturalWidth,cropStageHeight/cropImg.naturalHeight);const dispW=cropImg.naturalWidth*cropBaseScale;const dispH=cropImg.naturalHeight*cropBaseScale;cropOffsetX=(cropStageWidth-dispW)/2;cropOffsetY=(cropStageHeight-dispH)/2;applyCropTransform()};cropImg.src=src;cropOverlay.hidden=false}function closeProjectPhotoCrop(){cropOverlay.hidden=true;ed.cropTargetShootId=null}cropZoomSlider.addEventListener(`input`,()=>{cropZoom=Number(cropZoomSlider.value);applyCropTransform()});cropStage.addEventListener(`pointerdown`,e=>{cropActivePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});try{cropStage.setPointerCapture(e.pointerId)}catch(err){}if(cropActivePointers.size===1){cropDragging=true;cropDragStartX=e.clientX;cropDragStartY=e.clientY;cropDragOffsetStartX=cropOffsetX;cropDragOffsetStartY=cropOffsetY}else if(cropActivePointers.size===2){cropDragging=false;const[p1,p2]=[...cropActivePointers.values()];cropPinchPrevDist=Math.hypot(p2.x-p1.x,p2.y-p1.y)}});cropStage.addEventListener(`pointermove`,e=>{if(!cropActivePointers.has(e.pointerId))return;cropActivePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(cropActivePointers.size>=2){const[p1,p2]=[...cropActivePointers.values()];const dist=Math.hypot(p2.x-p1.x,p2.y-p1.y);if(cropPinchPrevDist>0){const rect=cropStage.getBoundingClientRect();const midX=(p1.x+p2.x)/2-rect.left;const midY=(p1.y+p2.y)/2-rect.top;const scale=cropBaseScale*cropZoom;const px=(midX-cropOffsetX)/scale;const py=(midY-cropOffsetY)/scale;const newZoom=Math.min(3,Math.max(1,cropZoom*(dist/cropPinchPrevDist)));cropOffsetX=midX-px*(cropBaseScale*newZoom);cropOffsetY=midY-py*(cropBaseScale*newZoom);cropZoom=newZoom;cropZoomSlider.value=String(cropZoom);applyCropTransform()}cropPinchPrevDist=dist}else if(cropDragging){cropOffsetX=cropDragOffsetStartX+(e.clientX-cropDragStartX);cropOffsetY=cropDragOffsetStartY+(e.clientY-cropDragStartY);applyCropTransform()}});function endCropPointer(e){cropActivePointers.delete(e.pointerId);if(cropActivePointers.size===1){const[remaining]=[...cropActivePointers.values()];cropDragging=true;cropDragStartX=remaining.x;cropDragStartY=remaining.y;cropDragOffsetStartX=cropOffsetX;cropDragOffsetStartY=cropOffsetY}else{cropDragging=false}}cropStage.addEventListener(`pointerup`,endCropPointer);cropStage.addEventListener(`pointercancel`,endCropPointer);document.getElementById(`cropCloseBtn`).addEventListener(`click`,closeProjectPhotoCrop);cropOverlay.addEventListener(`click`,e=>{if(e.target===cropOverlay)closeProjectPhotoCrop()});document.getElementById(`cropConfirmBtn`).addEventListener(`click`,()=>{const scale=cropBaseScale*cropZoom;const sWidth=cropStageWidth/scale;const sHeight=cropStageHeight/scale;const sx=-cropOffsetX/scale;const sy=-cropOffsetY/scale;const{width:outputWidth,height:outputHeight}=CROP_OUTPUT[cropMode];const canvas=document.createElement(`canvas`);canvas.width=outputWidth;canvas.height=outputHeight;canvas.getContext(`2d`).drawImage(cropImg,sx,sy,sWidth,sHeight,0,0,outputWidth,outputHeight);const dataUrl=canvas.toDataURL(`image/jpeg`,.7);const targetId=ed.cropTargetShootId;if(cropMode===`talent`){if(ed.talentModalDraft){ed.talentModalDraft.photo=dataUrl;ed.renderTalentModalPhoto()}closeProjectPhotoCrop()}else if(targetId){const idx=ed.state.shoots.findIndex(x=>x.id===targetId);if(idx!==-1){ed.state.shoots[idx]={...ed.state.shoots[idx],projectPhoto:dataUrl};ed.saveState();ed.savePhotoToIdb(ed.projectPhotoKey(targetId),dataUrl).catch(ed.noteStorageFull).then(()=>ed.onShootImagesChanged(targetId,{cover:true}));ed.renderAll()}closeProjectPhotoCrop();ed.closeShootOptions()}else{ed.pendingProjectPhoto=dataUrl;ed.scheduleShootAutosave();const coverShootId=ed.currentShootId;if(coverShootId){ed.savePhotoToIdb(ed.projectPhotoKey(coverShootId),dataUrl).catch(ed.noteStorageFull).then(()=>ed.onShootImagesChanged(coverShootId,{cover:true}))}closeProjectPhotoCrop();ed.closeImageViewer()}})};
;

