window.EyeParts=window.EyeParts||{};window.EyeParts.addShootPassedOn=function addShootPassedOn(ed){Object.assign(ed,{passFinalsOn,passedOnSlot,renderPassedOn});const C=()=>window.DFConnect;const D=()=>ed.refApi;const ready=()=>!!(D()&&C());async function passFinalsOn(shootId){if(!ready()||!D().inSuite()||!C().connectOn(`finals`))return null;if(ed.shootPageOpenOn(shootId))ed.saveShootNow();const shoot=ed.state.shoots.find(s=>s.id===shootId);if(!shoot||shoot.status!==`delivered`||ed.isVideoCategory(shoot.category))return null;const finals=await ed.idbGetImages(ed.finalImagesKey(shootId));if(!finals.length)return null;const[had]=await D().linksWhere({fromApp:`the-eye`,fromId:shootId,type:`finals`});if(had&&had.madeAt)return had;const title=shoot.title||``;const credits=C().shootCredits(shoot);return D().saveLink({...had||{},fromApp:`the-eye`,fromId:shootId,toApp:`contact-sheet`,toId:``,type:`finals`,title,count:finals.length,credits,caption:C().captionFor(title,credits),deliveredAt:shoot.deliveredAt||``})}let last={shootId:null,html:``};function passedOnSlot(){const html=last.shootId===ed.currentShootId?last.html:``;return`<div class="passed-on" id="shootPassedOn"${html?` data-drawn`:` hidden`}>${html}</div>`}async function renderPassedOn(){const shootId=ed.currentShootId;const delivered=document.getElementById(`shootStatus`).value===`delivered`;let html=``;if(ready()&&shootId&&delivered){const links=(await Promise.all([D().linksWhere({fromApp:`the-eye`,fromId:shootId}),D().linksWhere({toApp:`the-eye`,toId:shootId,type:`moodboard`})]).catch(()=>[[],[]])).flat();if(shootId!==ed.currentShootId)return;const{passed,came}=C().passedOnRows(links,shootId);const withHref=rows=>rows.map(r=>({...r,href:r.params?D().notebookUrl(r.app,r.params)||``:``}));const part=(title,rows)=>rows.length?ed.frontTitle(title)+C().recordHtml(withHref(rows)):``;html=part(`Passed on`,passed)+part(`Came in`,came)}const same=last.shootId===shootId&&last.html===html;last={shootId,html};const box=document.getElementById(`shootPassedOn`);if(!box)return;if(!same||!box.hasAttribute(`data-drawn`)){box.innerHTML=html;box.setAttribute(`data-drawn`,``)}box.hidden=!html}};
