window.EyeParts=window.EyeParts||{};window.EyeParts.addShootNotSure=function addShootNotSure(ed){Object.assign(ed,{loadNotSure,syncNotSure,notSureNow});const picked=new Set;const CHIPS={date:`dateNotSetBtn`,location:`locationNotSetBtn`,team:`teamNotSureBtn`};const hasPlace=()=>[`name`,`street`,`city`].some(k=>ed.hasText(ed.currentShootLocation[k]));function loadNotSure(shoot){picked.clear();(shoot&&shoot.notSure||[]).forEach(key=>picked.add(key));syncNotSure()}function notSureNow(data){return ed.stillNotSure({...data,notSure:[...picked]})}function syncNotSure(){Object.entries(CHIPS).forEach(([key,id])=>{const chip=document.getElementById(id);const on=picked.has(key)&&(key!==`team`||!ed.getTeamRequiredChoice());chip.classList.toggle(`active`,on);chip.setAttribute(`aria-pressed`,on?`true`:`false`)});document.getElementById(`dateNotSetBtn`).hidden=ed.hasText(document.getElementById(`shootDate`).value);document.getElementById(`locationNotSetBtn`).hidden=hasPlace()}function toggle(key){if(picked.has(key))picked.delete(key);else picked.add(key);syncNotSure();ed.scheduleShootAutosave()}document.getElementById(`dateNotSetBtn`).addEventListener(`click`,()=>toggle(`date`));document.getElementById(`locationNotSetBtn`).addEventListener(`click`,()=>toggle(`location`));document.getElementById(`teamNotSureBtn`).addEventListener(`click`,()=>{if(picked.has(`team`)&&!ed.getTeamRequiredChoice())return;picked.add(`team`);ed.setTeamRequiredChoice(``);syncNotSure();ed.scheduleShootAutosave()});[`teamRequiredNoBtn`,`teamRequiredYesBtn`].forEach(id=>document.getElementById(id).addEventListener(`click`,()=>{picked.delete(`team`);syncNotSure()}));document.getElementById(`shootDate`).addEventListener(`input`,syncNotSure);document.getElementById(`shootDate`).addEventListener(`change`,syncNotSure);new MutationObserver(syncNotSure).observe(document.getElementById(`shootLocationBtn`),{childList:true,characterData:true,subtree:true})};
