// ---- pages/shoot/multi-day.js ----
window.EyeParts=window.EyeParts||{};window.EyeParts.addShootMultiDay=function addShootMultiDay(ed){Object.assign(ed,{multiDayDatesText,multiDayMembership,resetMultiDayDraft,updateMultiDayRow,markShootModalAsSaved});const MULTI_DAY_MAX_DAYS=14;ed.multiDayPromptDates=null;ed.multiDayCreating=false;function addDaysToDateStr(dateStr,n){const d=ed.parseShootDate(dateStr);d.setDate(d.getDate()+n);return ed.formatDate(d)}function multiDayDateRange(startStr,endStr){const dates=[];let d=startStr;while(d<=endStr&&dates.length<=MULTI_DAY_MAX_DAYS){dates.push(d);d=addDaysToDateStr(d,1)}return dates}function multiDayDatesText(dates){const monthDay=ds=>ed.parseShootDate(ds).toLocaleDateString(undefined,{month:`short`,day:`numeric`});if(dates.length>4){return`${monthDay(dates[0])} – ${monthDay(dates[dates.length-1])} (${dates.length} days)`}return ed.joinWithAnd(dates.map((ds,i)=>i>0&&ds.slice(0,7)===dates[i-1].slice(0,7)?String(ed.parseShootDate(ds).getDate()):monthDay(ds)))}function multiDayMembership(){const shoot=ed.state.shoots.find(x=>x.id===ed.currentShootId);const project=shoot&&shoot.projectId?ed.findProject(shoot.projectId):null;return project?{shoot,project}:null}function resetMultiDayDraft(){document.getElementById(`shootMultiDay`).checked=false;const lastDayInput=document.getElementById(`shootLastDay`);lastDayInput.value=``;lastDayInput.removeAttribute(`min`);lastDayInput.removeAttribute(`max`);document.getElementById(`multiDayLastDayLabel`).hidden=true}function updateMultiDayRow(){resetMultiDayDraft();const label=document.getElementById(`multiDayLabel`);const membership=multiDayMembership();if(!membership){label.textContent=`Multi-day shoot`;return}const info=ed.projectDayInfo(membership.shoot);document.getElementById(`shootMultiDay`).checked=true;const lead=ed.projectLeadOf(membership.project);let mirrorText=``;if(lead&&lead.id===membership.shoot.id){mirrorText=` · mirrored to the other days`}else if(lead){const leadInfo=ed.projectDayInfo(lead);mirrorText=membership.shoot.followsLead?` · mirrors ${leadInfo?`Day ${leadInfo.day}`:`the first day`}`:` · has its own changes`}label.textContent=`Part of ${membership.project.name}${info?` · Day ${info.day} of ${info.total}`:``}${mirrorText}`}function setLastDayRange(startDate){const lastDayInput=document.getElementById(`shootLastDay`);lastDayInput.min=addDaysToDateStr(startDate,1);lastDayInput.max=addDaysToDateStr(startDate,MULTI_DAY_MAX_DAYS-1)}function markShootModalAsSaved(){if(ed.editingShootId===ed.currentShootId)return;ed.editingShootId=ed.currentShootId;document.getElementById(`deleteShootBtn`).hidden=false;document.getElementById(`shareShootBtn`).hidden=false;const isArchived=!document.getElementById(`unarchiveShootBtn`).hidden;document.getElementById(`completeShootBtn`).hidden=isArchived||document.getElementById(`shootStatus`).value!==`delivered`;ed.updateEnterShootModeBtnVisibility()}[`shootMultiDay`,`shootLastDay`].forEach(id=>{document.getElementById(id).addEventListener(`input`,e=>e.stopPropagation())});document.getElementById(`shootMultiDay`).addEventListener(`change`,async e=>{e.stopPropagation();const checkbox=e.target;const membership=multiDayMembership();if(membership){if(checkbox.checked)return;checkbox.checked=true;const shootId=membership.shoot.id;const ok=await ed.askConfirm({title:`Take this shoot out of ${membership.project.name}?`,text:`It stays as its own shoot.`,confirmLabel:`Take it out`,cancelLabel:`Keep it in`});const current=multiDayMembership();if(!ok||ed.shootModalOverlay.hidden||!current||current.shoot.id!==shootId)return;ed.saveShootNow();ed.setShootProject(current.shoot.id,``);ed.saveState();ed.renderAll();ed.refreshOpenStatBoxDetail();updateMultiDayRow();return}if(!checkbox.checked){resetMultiDayDraft();return}const startDate=document.getElementById(`shootDate`).value;if(!startDate){checkbox.checked=false;ed.showToast(`Set the shoot date first`);return}document.getElementById(`shootLastDay`).value=``;setLastDayRange(startDate);document.getElementById(`multiDayLastDayLabel`).hidden=false;maybeShowMultiDayNotice()});const MULTI_DAY_NOTICE_HIDDEN_KEY=`dailies_multi_day_notice_hidden_v1`;function maybeShowMultiDayNotice(){let hidden;try{hidden=localStorage.getItem(MULTI_DAY_NOTICE_HIDDEN_KEY)===`1`}catch(err){hidden=false}if(!hidden)document.getElementById(`multiDayNoticeOverlay`).hidden=false}document.getElementById(`multiDayNoticeOkBtn`).addEventListener(`click`,()=>{document.getElementById(`multiDayNoticeOverlay`).hidden=true});document.getElementById(`multiDayNoticeHideBtn`).addEventListener(`click`,()=>{try{localStorage.setItem(MULTI_DAY_NOTICE_HIDDEN_KEY,`1`)}catch(err){}document.getElementById(`multiDayNoticeOverlay`).hidden=true});document.getElementById(`shootLastDay`).addEventListener(`change`,e=>{e.stopPropagation();const lastDayInput=e.target;const lastDay=lastDayInput.value;if(!lastDay||multiDayMembership())return;if(lastDay.slice(0,4)<`1000`)return;const startDate=document.getElementById(`shootDate`).value;if(!startDate){resetMultiDayDraft();ed.showToast(`Set the shoot date first`);return}if(lastDay<=startDate){lastDayInput.value=``;ed.showToast(`Pick a last day after the shoot date`);return}const dates=multiDayDateRange(startDate,lastDay);if(dates.length>MULTI_DAY_MAX_DAYS){lastDayInput.value=``;ed.showToast(`Multi-day shoots can be up to ${MULTI_DAY_MAX_DAYS} days`);return}lastDayInput.blur();ed.openMultiDayPrompt(dates)});function syncMultiDayRowToShootDate(){if(multiDayMembership()){ed.saveShootNow();updateMultiDayRow();return}if(!document.getElementById(`shootMultiDay`).checked)return;const startDate=document.getElementById(`shootDate`).value;if(!startDate){resetMultiDayDraft();return}document.getElementById(`shootLastDay`).value=``;setLastDayRange(startDate)}document.getElementById(`shootDate`).addEventListener(`change`,syncMultiDayRowToShootDate)};
