window.EyeParts=window.EyeParts||{};window.EyeParts.addShootMultiDayPrompt=function addShootMultiDayPrompt(ed){Object.assign(ed,{openMultiDayPrompt});let backOnScheduleAskFor=null;async function askBackOnSchedule(){const shootId=backOnScheduleAskFor;backOnScheduleAskFor=null;const select=document.getElementById(`shootStatus`);const status=select.value;const date=document.getElementById(`shootDate`).value;if(!ed.shootPageOpenOn(shootId)||!ed.isOffScheduleShoot({status})||!date||date===ed.currentOffScheduleDate)return;const label=ed.STATUS_LABELS[status].toLowerCase();const backOn=await ed.askConfirm({title:`New date. Is it back on?`,text:`This shoot is ${label}. Put it back on the schedule for ${ed.prettyDate(date)}, or keep it ${label} for now?`,cancelLabel:`Keep ${label}`,confirmLabel:`Back on the schedule`});if(!backOn||!ed.shootPageOpenOn(shootId)||select.value!==status)return;select.value=`planning`;select.dispatchEvent(new Event(`change`,{bubbles:true}));ed.saveShootNow()}document.getElementById(`shootDate`).addEventListener(`change`,e=>{if(!ed.isOffScheduleShoot({status:document.getElementById(`shootStatus`).value}))return;backOnScheduleAskFor=ed.currentShootId;if(document.activeElement!==e.target)askBackOnSchedule()});document.getElementById(`shootDate`).addEventListener(`blur`,()=>{if(backOnScheduleAskFor)askBackOnSchedule()});document.getElementById(`shootStatus`).addEventListener(`change`,()=>{if(!ed.multiDayMembership())return;ed.saveShootNow();ed.updateMultiDayRow()});function openMultiDayPrompt(dates){ed.multiDayPromptDates=dates;const term=ed.moodboardTerm(document.getElementById(`shootCategory`).value).toLowerCase();document.getElementById(`multiDayPromptText`).textContent=`This makes a separate shoot for each day: ${ed.multiDayDatesText(dates)}. Everything on Day 1 (talent, team, location, concept, notes, ${term} and lighting setups) is mirrored to the other days, including any changes you make to Day 1 later. Each day keeps its own date, times, status, shot list and reflection. Note: if you change anything on another day yourself, that day keeps its own version and won't pick up later changes to Day 1.`;const talent=ed.currentTalents.find(t=>ed.hasText(t.name));document.getElementById(`multiDayProjectNameInput`).value=document.getElementById(`shootTitle`).value.trim()||(talent?talent.name.trim():``)||ed.UNTITLED_PROJECT_NAME;document.getElementById(`multiDayPromptOverlay`).hidden=false}function closeMultiDayPrompt(){document.getElementById(`multiDayPromptOverlay`).hidden=true;ed.multiDayPromptDates=null}document.getElementById(`multiDayPromptCancelBtn`).addEventListener(`click`,()=>{if(ed.multiDayCreating)return;closeMultiDayPrompt();ed.resetMultiDayDraft()});document.getElementById(`multiDayProjectNameInput`).addEventListener(`keydown`,e=>{if(e.key===`Enter`)document.getElementById(`multiDayPromptCreateBtn`).click()});document.getElementById(`multiDayPromptCreateBtn`).addEventListener(`click`,async()=>{if(ed.multiDayCreating)return;const dates=ed.multiDayPromptDates;if(!dates||dates.length<2||ed.shootModalOverlay.hidden||ed.multiDayMembership()){closeMultiDayPrompt();ed.updateMultiDayRow();return}ed.multiDayCreating=true;const createBtn=document.getElementById(`multiDayPromptCreateBtn`);createBtn.textContent=`Creating…`;let project=null;let sourceId=null;try{const name=document.getElementById(`multiDayProjectNameInput`).value.trim()||ed.UNTITLED_PROJECT_NAME;clearTimeout(ed.shootSaveTimer);const day1=ed.autosaveShoot(true);sourceId=day1.id;ed.markShootModalAsSaved();project=ed.createProject(name);ed.setShootProject(sourceId,project.id);ed.saveState();const source=ed.state.shoots.find(x=>x.id===sourceId);try{for(const date of dates.slice(1)){const day=await ed.copyShootForProject(source,`day`,{date,projectId:project.id});if(day&&day.projectId===project.id){day.followsLead=true;day.mirrorSig=ed.mirrorSignature(day)}}}catch(err){}const liveProject=ed.findProject(project.id);const lead=ed.state.shoots.find(x=>x.id===sourceId);if(liveProject&&lead){liveProject.leadShootId=sourceId;liveProject.mirrorSig=ed.mirrorSignature(lead)}ed.saveState()}finally{ed.multiDayCreating=false;createBtn.textContent=`Create days`}closeMultiDayPrompt();ed.renderAll();ed.refreshOpenStatBoxDetail();if(!ed.shootModalOverlay.hidden&&ed.currentShootId===sourceId)ed.updateMultiDayRow();const total=ed.projectMembers(project.id).length;ed.showToast(total===dates.length?`${total} days created in ${project.name}`:`Only ${total} of ${dates.length} days could be created in ${project.name}`)})};
