window.EyeParts=window.EyeParts||{};window.EyeParts.addShootClose=function addShootClose(ed){Object.assign(ed,{closeShootModal,deleteShootById,askDeleteShoot,syncPaneTrackHeight});function closeShootModal(){ed.endShootWizard({closing:true});clearTimeout(ed.shootSaveTimer);ed.autosaveShoot();if(!ed.state.shoots.some(x=>x.id===ed.currentShootId)){ed.dropRefBoardsFor(ed.currentShootId);ed.idbDeleteImages(ed.currentShootId).catch(()=>{});ed.idbDeleteImages(ed.finalImagesKey(ed.currentShootId)).catch(()=>{});ed.idbDeleteImages(ed.projectPhotoKey(ed.currentShootId)).catch(()=>{});ed.currentTalents.forEach(t=>{if(t.id)ed.idbDeleteImages(ed.talentPhotoKey(ed.currentShootId,t.id)).catch(()=>{})})}if(!ed.shootModalOverlay.hidden)ed.unlockBodyScroll();ed.shootModalOverlay.hidden=true;ed.editingShootId=null;ed.renderAll();ed.refreshOpenStatBoxDetail()}document.getElementById(`saveShootBtn`).addEventListener(`click`,closeShootModal);function deleteShootById(id){const doomed=ed.state.shoots.find(x=>x.id===id);ed.state.shoots=ed.state.shoots.filter(x=>x.id!==id);ed.state.journalEntries=ed.state.journalEntries.filter(e=>e.sourceShootId!==id);ed.pruneEmptyProjects();ed.idbDeleteImages(id).catch(()=>{});ed.idbDeleteImages(ed.finalImagesKey(id)).catch(()=>{});ed.dropRefBoardsFor(id);if(doomed)ed.shootPhotoKeys(doomed).forEach(k=>ed.idbDeleteImages(k).catch(()=>{}));ed.saveState()}function askDeleteShoot(){return ed.askConfirm({title:`Delete this shoot?`,text:`This can't be undone.`,confirmLabel:`Delete shoot`,cancelLabel:`Keep it`,danger:true})}document.getElementById(`deleteShootBtn`).addEventListener(`click`,async()=>{const id=ed.currentShootId;if(!await askDeleteShoot()||ed.currentShootId!==id||ed.shootModalOverlay.hidden)return;clearTimeout(ed.shootSaveTimer);deleteShootById(id);if(!ed.shootModalOverlay.hidden)ed.unlockBodyScroll();ed.shootModalOverlay.hidden=true;ed.editingShootId=null;ed.renderAll();ed.refreshOpenStatBoxDetail()});document.getElementById(`shareShootBtn`).addEventListener(`click`,()=>{ed.saveShootNow();if(ed.editingShootId)ed.openPdfSectionsModal(ed.editingShootId)});function syncPaneTrackHeight(track){const panes=[...track.children].filter(el=>el.classList.contains(`options-pane`));let idx=0;if(track.classList.contains(`show-fifth`))idx=4;else if(track.classList.contains(`show-fourth`))idx=3;else if(track.classList.contains(`show-third`))idx=2;else if(track.classList.contains(`show-second`))idx=1;const active=panes[idx];if(active)track.style.height=active.offsetHeight+`px`}};
