// ---- components/toast.js ----
window.EyeParts=window.EyeParts||{};window.EyeParts.addToast=function addToast(ed){Object.assign(ed,{showToast,showNoticeToast,showUndoToast,fitButtonPair});let toastTimer=null;let undoToastLive=false;let heldNotices=[];function showToast(message,ms=3200){const toast=document.getElementById(`toast`);toast.textContent=message;toast.hidden=false;undoToastLive=false;clearTimeout(toastTimer);toastTimer=setTimeout(hideToast,ms)}function hideToast(){document.getElementById(`toast`).hidden=true;undoToastLive=false;showHeldNotice()}function showNoticeToast(message,ms,stillTrue){if(undoToastLive){heldNotices=heldNotices.filter(n=>n.message!==message);heldNotices.push({message,ms,stillTrue});return}showToast(message,ms)}function showHeldNotice(){while(heldNotices.length){const next=heldNotices.shift();if(next.stillTrue&&!next.stillTrue())continue;showToast(next.message,next.ms);return}}function showUndoToast(message,onUndo){const toast=document.getElementById(`toast`);toast.textContent=message+` `;const undo=document.createElement(`button`);undo.type=`button`;undo.className=`toast-undo-btn`;undo.textContent=`Undo`;undo.addEventListener(`click`,()=>{clearTimeout(toastTimer);toast.hidden=true;undoToastLive=false;onUndo();if(toast.hidden)showHeldNotice()});toast.appendChild(undo);toast.hidden=false;undoToastLive=true;clearTimeout(toastTimer);toastTimer=setTimeout(hideToast,5e3)}function fitButtonPair(row){row.classList.remove(`modal-actions-stacked`);const rowWidth=row.getBoundingClientRect().width;if(!rowWidth)return;const half=(rowWidth-(parseFloat(getComputedStyle(row).columnGap)||0))/2;const widths=[...row.querySelectorAll(`button`)].filter(b=>!b.hidden).map(b=>b.getBoundingClientRect().width);if(Math.max(0,...widths)>half+3)row.classList.add(`modal-actions-stacked`)}};
