window.EyeParts=window.EyeParts||{};window.EyeParts.addConfirm=function addConfirm(ed){Object.assign(ed,{askConfirm});let appConfirmResolve=null;let appConfirmOpenedAt=0;function askConfirm({title=``,text=``,confirmLabel=`OK`,cancelLabel=`Cancel`,danger=false}={}){if(appConfirmResolve)settleAppConfirm(false);const focused=document.activeElement;if(focused&&focused!==document.body&&typeof focused.blur===`function`)focused.blur();document.getElementById(`appConfirmTitle`).textContent=title;const textEl=document.getElementById(`appConfirmText`);textEl.textContent=text;textEl.hidden=!text;const ok=document.getElementById(`appConfirmOkBtn`);ok.textContent=confirmLabel;ok.className=danger?`danger`:`primary`;document.getElementById(`appConfirmCancelBtn`).textContent=cancelLabel;appConfirmOpenedAt=performance.now();document.getElementById(`appConfirmOverlay`).hidden=false;ed.fitButtonPair(document.getElementById(`appConfirmActions`));return new Promise(resolve=>{appConfirmResolve=resolve})}function settleAppConfirm(answer){document.getElementById(`appConfirmOverlay`).hidden=true;const resolve=appConfirmResolve;appConfirmResolve=null;if(resolve)resolve(answer)}document.getElementById(`appConfirmOkBtn`).addEventListener(`click`,()=>{if(performance.now()-appConfirmOpenedAt<400)return;settleAppConfirm(true)});document.getElementById(`appConfirmCancelBtn`).addEventListener(`click`,()=>settleAppConfirm(false))};
