window.EyeParts=window.EyeParts||{};window.EyeParts.addLoadLib=function addLoadLib(ed){const loading=new Map;function loadLib(src,name){if(!loading.has(src))loading.set(src,window[name]?Promise.resolve(window[name]):addTag(src,name));return loading.get(src)}function addTag(src,name){return new Promise((resolve,reject)=>{const tag=document.createElement(`script`);tag.src=src;tag.onload=()=>resolve(window[name]);tag.onerror=()=>{loading.delete(src);tag.remove();reject(new Error(`${src} did not load`))};document.head.appendChild(tag)})}Object.assign(ed,{loadLib})};
