window.EyeParts=window.EyeParts||{};window.EyeParts.addPdfPreview=function addPdfPreview(ed){Object.assign(ed,{hashString,openPdfPreview});ed.pdfPreviewBlob=null;ed.pdfPreviewFilename=``;let callSheetCache=null;function hashString(str){let h=5381;for(let i=0;i<str.length;i++)h=(h<<5)+h+str.charCodeAt(i)|0;return h>>>0}async function callSheetCacheKey(s,sections){const parts=[s.id,JSON.stringify(sections),JSON.stringify(s),JSON.stringify(ed.normalizePhotographer(ed.state.photographer))];if(sections.moodboard){const imgs=await ed.idbGetImages(s.id);parts.push(imgs.map(img=>`${(img.src||``).length}:${hashString(img.src||``)}:${img.caption||``}`).join(`|`))}return parts.map(part=>`${part.length}:${hashString(part)}`).join(`/`)}async function openPdfPreview(id,chosenSections){const s=ed.state.shoots.find(x=>x.id===id);if(!s)return;ed.busyTasks++;try{const key=await callSheetCacheKey(s,chosenSections);if(!callSheetCache||callSheetCache.key!==key){ed.showToast(`Building call sheet…`);const doc=await ed.buildShootPdf(s,chosenSections);const dateLabel=ed.formatDateDots(s.date);const nameOrTalent=s.title||ed.primaryTalentName(s)||`Shoot`;const title=dateLabel?`${dateLabel} · ${nameOrTalent} call sheet`:`${nameOrTalent} call sheet`;const safeName=title.replace(/—/g,`-`).replace(/[^\w\- .]+/g,``).trim()||`call sheet`;callSheetCache={key,blob:doc.output(`blob`),filename:`${safeName}.pdf`}}ed.pdfPreviewBlob=callSheetCache.blob;ed.pdfPreviewFilename=callSheetCache.filename;ed.showPdfPreview(ed.pdfPreviewBlob)}catch(err){console.error(`Failed to build shoot PDF`,err);ed.showToast(`Could not create PDF`)}finally{ed.busyTasks--}}};
;

