window.EyeParts=window.EyeParts||{};window.EyeParts.addAppMenuRestore=function addAppMenuRestore(ed){const NOT_A_BACKUP=`That file isn't a backup from this app. Nothing was changed.`;document.getElementById(`importDataBtn`).addEventListener(`click`,()=>{ed.closeAppMenu();window.DFData.pickFiles(window.DFRestore.PICK).then(async picked=>{if(!picked.length)return;const pick=await window.DFRestore.which(picked,`the-eye`);if(!pick)return;if(pick.all){restoreAllFour(picked);return}const files=pick.files;if(await window.DFData.isZipFile(files[0])){pendingImportFiles=files;importConfirmOverlay.hidden=false;return}const reader=new FileReader;reader.onload=()=>{try{const payload=JSON.parse(reader.result);if(!payload||!payload.state||!Array.isArray(payload.state.shoots))throw new Error(`bad shape`);pendingImportPayload=payload;importConfirmOverlay.hidden=false}catch(err){ed.showToast(NOT_A_BACKUP)}};reader.onerror=()=>ed.showToast(NOT_A_BACKUP);reader.readAsText(files[0])}).catch(()=>ed.showToast(NOT_A_BACKUP))});let pendingImportPayload=null;let pendingImportFiles=null;const importConfirmOverlay=document.getElementById(`importConfirmOverlay`);document.getElementById(`importBackupFirstBtn`).addEventListener(`click`,ed.exportAllData);document.getElementById(`cancelImportBtn`).addEventListener(`click`,()=>{pendingImportPayload=null;pendingImportFiles=null;importConfirmOverlay.hidden=true});function adoptBackupState(saved){const importedShoots=Array.isArray(saved.shoots)?saved.shoots:[];ed.migrateIdeaPhaseStatus(importedShoots);ed.normalizeShootStatuses(importedShoots);const importedProjects=ed.normalizeProjects(saved.projects,importedShoots);ed.state={shoots:importedShoots,projects:importedProjects,frameworks:Array.isArray(saved.frameworks)&&saved.frameworks.length?saved.frameworks:ed.seedFrameworks(),journalEntries:Array.isArray(saved.journalEntries)?saved.journalEntries:[],titleDisplayMode:saved.titleDisplayMode===`title`?`title`:`talent`,presentation:ed.normalizePresentation(saved.presentation||ed.state.presentation),defaultCountry:typeof saved.defaultCountry===`string`?saved.defaultCountry:``,dismissedLocationKeys:Array.isArray(saved.dismissedLocationKeys)?saved.dismissedLocationKeys:[],dismissedTeamMemberKeys:Array.isArray(saved.dismissedTeamMemberKeys)?saved.dismissedTeamMemberKeys:[],dismissedTalentKeys:Array.isArray(saved.dismissedTalentKeys)?saved.dismissedTalentKeys:[],dismissedLightingSetupKeys:Array.isArray(saved.dismissedLightingSetupKeys)?saved.dismissedLightingSetupKeys:[],photographer:ed.normalizePhotographer(saved.photographer)};ed.saveState();ed.applyAppColor(ed.state.presentation.color);ed.refreshStickers();ed.renderAll();ed.showToast(`Backup restored`);ed.migrateInlinePhotos().then(ed.hydratePhotos).then(()=>ed.renderAll()).catch(()=>{})}document.getElementById(`confirmImportBtn`).addEventListener(`click`,()=>{const payload=pendingImportPayload;const files=pendingImportFiles;importConfirmOverlay.hidden=true;pendingImportPayload=null;pendingImportFiles=null;if(files){restoreZipBackup(files);return}if(!payload)return;const imageWrites=Object.entries(payload.images||{}).map(([key,imgs])=>ed.idbSetImages(key,imgs));imageWrites.push(ed.restoreRefBoards(payload.refBoards).catch(()=>{}));ed.busyTasks++;Promise.all(imageWrites).then(()=>{adoptBackupState(payload.state)},err=>{console.error(`Restore failed`,err);if(ed.isStorageFullError(err))ed.noteStorageFull(err);else ed.showToast(`Couldn't restore that backup`)}).finally(()=>{ed.busyTasks--})});function restoreAllFour(files){ed.busyTasks++;window.DFRestore.confirm(files,{done:()=>{let saved=null;try{saved=JSON.parse(localStorage.getItem(ed.STORAGE_KEY))}catch(e){saved=null}Promise.resolve(ed.refApi?ed.loadRefBoardShoots().catch(()=>{}):null).then(()=>{if(saved&&Array.isArray(saved.shoots))adoptBackupState(saved)}).finally(()=>{ed.busyTasks--})}}).then(done=>{if(!done)ed.busyTasks--})}function restoreZipBackup(files){let saved=null;ed.busyTasks++;ed.showToast(`Restoring the backup`,6e5);window.DFData.restoreZip(files,{databases:ed.BACKUP_DBS,check:async local=>{try{saved=JSON.parse(await local(ed.STORAGE_KEY))}catch(e){saved=null}if(!saved||!Array.isArray(saved.shoots))throw new Error(NOT_A_BACKUP)}}).then(()=>ed.refApi?ed.loadRefBoardShoots().catch(()=>{}):null).then(()=>adoptBackupState(saved)).catch(err=>{console.error(`Restore failed`,err);ed.showToast(err.message||`Couldn't restore that backup`)}).finally(()=>{ed.busyTasks--})}};
