window.EyeParts=window.EyeParts||{};window.EyeParts.addShootModeQuickReview=function addShootModeQuickReview(ed){const SHOOT_MODE_DIRECTION_FIELDS=[[`premise`,`Concept`,()=>document.getElementById(`shootPremise`).maxLength||300],[`character`,`Character/Personality`,1e3],[`worldNotes`,`World-building notes`,1e3],[`shootGoals`,`Shoot goals`,1e3],[`elevatorPitch`,`Elevator pitch`,150],[`talentDirections`,`Directions for talent`,1e3],[`teamDirections`,`Directions for team`,1e3]];function renderShootModeReviewField(label,value,maxLength,onSave){const filled=ed.hasText(value);const btn=document.createElement(`button`);btn.type=`button`;btn.className=`shoot-mode-review-field`;btn.innerHTML=`
      <p class="shoot-mode-review-label">${ed.escapeHtml(label)}</p>
      <p class="shoot-mode-review-value${filled?``:` shoot-mode-review-empty`}">${filled?ed.escapeHtml(value):`Tap to add`}</p>
    `;btn.addEventListener(`click`,()=>{ed.openExpandField({title:label,value:value||``,maxLength,onSave})});return btn}let shootModeReviewAddedSetups=new Set;function openShootModeReview(kind,isRefresh){const shootId=ed.getShootModeShootId();const shoot=shootId?ed.state.shoots.find(s=>s.id===shootId):null;if(!shoot)return;const body=document.getElementById(`shootModeReviewBody`);body.innerHTML=``;if(!isRefresh){shootModeReviewAddedSetups=new Set;const focused=document.activeElement;if(focused&&focused!==document.body&&typeof focused.blur===`function`)focused.blur()}const refresh=()=>openShootModeReview(kind,true);const commit=()=>{ed.saveState();refresh();ed.renderAll()};if(kind===`direction`){document.getElementById(`shootModeReviewTitle`).textContent=`Direction`;SHOOT_MODE_DIRECTION_FIELDS.filter(([key])=>ed.directionFieldApplies(shoot,key)).forEach(([key,label,maxLength])=>{const limit=typeof maxLength===`function`?maxLength():maxLength;body.appendChild(renderShootModeReviewField(label,shoot[key]||``,limit,newValue=>{shoot[key]=newValue;commit()}))})}else{document.getElementById(`shootModeReviewTitle`).textContent=`Lighting setups`;const setups=(shoot.lightingSetups||[]).filter(item=>shootModeReviewAddedSetups.has(item)||ed.hasText(item.name)||ed.hasText(item.characteristics)||ed.hasText(item.description));if(!setups.length){body.innerHTML=`<p class="shoot-mode-empty">No lighting setups logged for this shoot.</p>`}else{setups.forEach((item,idx)=>{const group=document.createElement(`div`);group.className=`shoot-mode-review-setup`;const name=document.createElement(`p`);name.className=`shoot-mode-review-setup-name`;name.textContent=ed.hasText(item.name)?item.name:`Setup ${idx+1}`;name.addEventListener(`click`,()=>{ed.openExpandField({title:`Setup name`,value:item.name||``,maxLength:200,onSave:newValue=>{item.name=newValue;commit()}})});group.appendChild(name);group.appendChild(renderShootModeReviewField(`Characteristics`,item.characteristics||``,1e3,newValue=>{item.characteristics=newValue;commit()}));group.appendChild(renderShootModeReviewField(`Description`,item.description||``,1e3,newValue=>{item.description=newValue;commit()}));body.appendChild(group)})}const addSetupBtn=document.createElement(`button`);addSetupBtn.type=`button`;addSetupBtn.className=`primary small-btn shoot-mode-add-shot-btn`;addSetupBtn.textContent=`+ Add lighting setup`;addSetupBtn.addEventListener(`click`,()=>{if(!Array.isArray(shoot.lightingSetups))shoot.lightingSetups=[];const item={id:ed.uid(),name:``,characteristics:``,description:``};shoot.lightingSetups.push(item);shootModeReviewAddedSetups.add(item);commit();body.scrollTop=body.scrollHeight;ed.openExpandField({title:`Setup name`,value:``,maxLength:200,onSave:newValue=>{item.name=newValue;commit()}})});body.appendChild(addSetupBtn)}document.getElementById(`shootModeReviewOverlay`).hidden=false}document.getElementById(`shootModeReviewDirectionBtn`).addEventListener(`click`,()=>openShootModeReview(`direction`));document.getElementById(`shootModeReviewLightingBtn`).addEventListener(`click`,()=>openShootModeReview(`lighting`));document.getElementById(`shootModeReviewCloseBtn`).addEventListener(`click`,()=>{document.getElementById(`shootModeReviewOverlay`).hidden=true});document.getElementById(`shootModeReviewOkBtn`).addEventListener(`click`,()=>{document.getElementById(`shootModeReviewOverlay`).hidden=true})};
