window.EyeParts=window.EyeParts||{};window.EyeParts.addNoticesShootDay=function addNoticesShootDay(ed){Object.assign(ed,{resumeShootModeIfActive});function resumeShootModeIfActive(){const id=ed.getShootModeShootId();if(!id)return false;const shoot=ed.state.shoots.find(s=>s.id===id);if(shoot&&shoot.date&&shoot.date<ed.effectiveReportDateStr()){ed.setShootModeShootId(null);return false}return ed.openShootMode(id)}};
