window.EyeParts=window.EyeParts||{};window.EyeParts.addBookOpen=function addBookOpen(ed,notebook){Object.assign(notebook,{remember,measure,placeTabHits,show});const SCREENS=[...document.querySelectorAll(`.tabbar .tab`)].map(tab=>({view:tab.dataset.view,name:tab.textContent.trim()}));notebook.SCREENS=SCREENS;const sideTabs=document.getElementById(`bookSideTabs`);const tabHits=document.getElementById(`bookTabHits`);sideTabs.innerHTML=SCREENS.map((s,i)=>`<i class="${i%2?`n`:`y`}" style="--t:${i};--i:${3+i*3}"><span>${s.name}</span></i>`).join(``);tabHits.innerHTML=SCREENS.map(s=>`<button type="button" class="nb-hit nb-hit-tab" data-view="${s.view}" aria-label="Open at ${s.name}"></button>`).join(``);function remember(state){try{localStorage.setItem(notebook.BOOK_KEY,state)}catch(err){}ed.queueLastPlace()}function measure(){const vw=window.innerWidth;const vh=ed.screenHeightNow();const W=Math.min(vw*.78,vh*.66*notebook.RATIO,460);const H=W/notebook.RATIO;const k=Math.min(1,(vw-14)/(2*W),vh*.82/H);notebook.book.style.setProperty(`--W`,`${W}px`);notebook.book.style.setProperty(`--H`,`${H}px`);notebook.book.style.setProperty(`--k`,String(k));const cos=Math.cos(notebook.TURNED);const sin=Math.sin(notebook.TURNED);const depth=(notebook.STACK+1)*W*.0112;const seen=[[-W/2,0],[W/2,0],[-W/2,-depth],[W/2+W*notebook.TAB_OUT,-depth*.8]].map(([x,d])=>(x*cos-d*sin)*notebook.PERSPECTIVE/(notebook.PERSPECTIVE-(x*sin+d*cos)));notebook.book.style.setProperty(`--shut-x`,`${-(Math.min(...seen)+Math.max(...seen))/2/cos}px`);ed.relayStickers();const OVER=12;notebook.book.style.setProperty(`--zoom-x`,`${vw/2}px`);notebook.book.style.setProperty(`--zoom-y`,`0px`);notebook.book.style.setProperty(`--zoom-sx`,String((vw+OVER)/.975/W));notebook.book.style.setProperty(`--zoom-rx`,String((vw+OVER)/.984/W));notebook.book.style.setProperty(`--zoom-sy`,String((vh+2*OVER)/.962/H))}function setMode(mode){if(mode!==`closed`)notebook.settleTurn();notebook.book.className=`nb ${mode}`}function placeTabHits(){const before=notebook.book.className;const turned=notebook.spinEl.style.transform;notebook.spinEl.style.transform=``;notebook.book.className=`nb no-anim closed`;const rects=[...sideTabs.children].map(el=>el.getBoundingClientRect());const hits=[...tabHits.children];rects.forEach((r,i)=>{const above=i?(rects[i-1].bottom+r.top)/2:r.top-4;const below=i<rects.length-1?(r.bottom+rects[i+1].top)/2:r.bottom+4;hits[i].style.cssText=`left:${r.left-12}px;right:0;top:${above}px;height:${below-above}px`});notebook.book.className=before;notebook.spinEl.style.transform=turned;void notebook.book.offsetWidth}function show(mode){if(mode!==`closed`)notebook.settleTurn();measure();notebook.overlay.hidden=false;placeTabHits();notebook.book.className=`nb no-anim ${mode}`;void notebook.book.offsetWidth}function leaveTo(mode,then){clearTimeout(notebook.timer);setMode(mode);notebook.timer=setTimeout(()=>{notebook.overlay.hidden=true;remember(`open`);notebook.settleScreenGap();if(then)then()},notebook.ZOOM_MS)}function sheets(count,side){return Array.from({length:count},(_,i)=>`${side*(i+1)*1.2}px 0 0 ${i%2?`#e4e4e4`:`#fff`}`).join(`,`)}function openBook(view){clearTimeout(notebook.timer);const at=SCREENS.findIndex(s=>s.view===view);if(at>0){document.getElementById(`bookDividerTitle`).textContent=SCREENS[at].name;document.getElementById(`bookDividerFace`).style.boxShadow=sheets(2+at*3,-1);document.getElementById(`bookRightPage`).style.boxShadow=sheets(2+(SCREENS.length-1-at)*3,1)}setMode(at>0?`opened at-section`:`opened`);notebook.timer=setTimeout(()=>{document.querySelector(`.tabbar .tab[data-view="${view}"]`).click();leaveTo(at>0?`opened at-section zoom-r`:`opened zoom-l`)},at>0?notebook.SECTION_MS:notebook.OPEN_MS)}document.getElementById(`bookOpenHit`).addEventListener(`click`,()=>openBook(`overview`));tabHits.addEventListener(`click`,e=>{const hit=e.target.closest(`[data-view]`);if(hit)openBook(hit.dataset.view)});document.getElementById(`shutBookBtn`).addEventListener(`click`,()=>{if(window.DF_SUITE){window.DF_SUITE.home();return}clearTimeout(notebook.timer);ed.clearPan();ed.screenAt.overview=0;ed.drawScreenPage(`overview`);show(`opened zoom-l`);setMode(`closed`);remember(`shut`)})};
