window.EyeParts=window.EyeParts||{};window.EyeParts.addBookNudge=function addBookNudge(ed,notebook){let nudgeRestUntil=0;let nudgeWaitTimer=0;const settle=()=>document.documentElement.classList.add(`settled`);if(!document.documentElement.classList.contains(`nb-installed`))settle();else setTimeout(settle,3500);function nudgeShortScreen(tries=3){if(notebook.nudging||!tries||!ed.screenShortHeight)return;const field=document.activeElement;if(field&&field.matches(`input, textarea, select, [contenteditable]`))return;if(document.body.style.position===`fixed`)return;clearTimeout(nudgeWaitTimer);if(performance.now()-ed.lastScrollAt<250){nudgeWaitTimer=setTimeout(()=>nudgeShortScreen(tries),300);return}notebook.nudging=true;const root=document.documentElement;root.classList.add(`nb-nudge`);const grow=document.createElement(`div`);grow.setAttribute(`aria-hidden`,`true`);grow.style.cssText=`height: 160px; pointer-events: none;`;document.body.appendChild(grow);setTimeout(()=>{const y=window.scrollY;const to=y>0?y-1:y+1;window.scrollTo(0,to);setTimeout(()=>{if(Math.abs(window.scrollY-to)<1.5)window.scrollTo(0,y);setTimeout(()=>{root.classList.remove(`nb-nudge`);grow.remove();setTimeout(()=>{notebook.nudging=false;notebook.settleScreenGap();if(!ed.screenShortHeight)settle();else if(tries>1)nudgeShortScreen(tries-1);else holdScreen()},200)},120)},40)},30)}function holdScreen(){const root=document.documentElement;notebook.nudging=true;root.classList.add(`nb-hold`);setTimeout(()=>{const y=window.scrollY;const to=y>0?y-1:y+1;window.scrollTo(0,to);setTimeout(()=>{if(Math.abs(window.scrollY-to)<1.5)window.scrollTo(0,y);setTimeout(()=>{notebook.nudging=false;notebook.settleScreenGap();if(ed.screenShortHeight){root.classList.remove(`nb-hold`);nudgeRestUntil=performance.now()+5e3}settle()},200)},60)},40)}const settleAndNudge=()=>{notebook.settleScreenGap();if(!ed.screenShortHeight){settle();return}if(!notebook.nudging){document.documentElement.classList.remove(`settled`);setTimeout(settle,2500)}nudgeShortScreen()};ed.onPageLetGo=settleAndNudge;[300,1200].forEach(ms=>setTimeout(settleAndNudge,ms));if(window.ResizeObserver){let moves=[];let calmTimer=0;const follow=new ResizeObserver(()=>{const now=performance.now();moves=moves.filter(t=>now-t<4e3);if(moves.length>=4){clearTimeout(calmTimer);calmTimer=setTimeout(notebook.settleScreenGap,4100);return}if(notebook.settleScreenGap())moves.push(now)});follow.observe(ed.layoutBoxProbe);follow.observe(ed.smallHeightProbe)}document.addEventListener(`focusout`,()=>setTimeout(notebook.settleScreenGap,460));window.addEventListener(`pageshow`,settleAndNudge);document.addEventListener(`visibilitychange`,()=>{if(!document.hidden)settleAndNudge()});if(window.visualViewport)window.visualViewport.addEventListener(`resize`,()=>setTimeout(notebook.settleScreenGap,120));let lastTouchCheck=0;document.addEventListener(`touchend`,()=>{const now=performance.now();if(now-lastTouchCheck<1e3)return;lastTouchCheck=now;setTimeout(()=>{notebook.settleScreenGap();if(performance.now()>nudgeRestUntil)nudgeShortScreen()},60)},{passive:true})};
