window.EyeParts=window.EyeParts||{};window.EyeParts.addSunStickerCreases=function addSunStickerCreases(ed,sun){Object.assign(sun,{placeOnCover,creaseArt});function placeOnCover(el,sticker){el.style.left=`${sticker.x*100}%`;el.style.top=`${sticker.y*100}%`;el.style.width=`${sticker.size*100}%`;el.style.setProperty(`--r`,String(sun.stickerRatio(sticker)))}const creases=new Map;sun.creases=creases;function creaseArt(sticker){if(creases.has(sticker.id))return creases.get(sticker.id);let seed=2166136261;for(let i=0;i<sticker.id.length;i++)seed=Math.imul(seed^sticker.id.charCodeAt(i),16777619);const rnd=()=>{seed=seed+1831565813|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};const ratio=sun.stickerRatio(sticker);const w=ratio>=1?520:Math.round(520*ratio);const h=ratio>=1?Math.round(520/ratio):520;const canvas=document.createElement(`canvas`);canvas.width=w;canvas.height=h;const g=canvas.getContext(`2d`);if(!g)return``;const big=Math.max(w,h);const ease=u=>u<=0?1:u>=1?0:1-u*u*(3-2*u);const ink=a=>`rgba(62, 44, 28, ${Math.max(0,a).toFixed(4)})`;const patches=4+Math.floor(rnd()*3);for(let i=0;i<patches;i++){const x=rnd()*w;const y=rnd()*h;const r=big*(.2+rnd()*.3);const peak=.06+rnd()*.07;const shade=g.createRadialGradient(x,y,0,x,y,r);for(let s=0;s<=8;s++)shade.addColorStop(s/8,ink(peak*ease(s/8)));g.fillStyle=shade;g.fillRect(0,0,w,h)}const band=document.createElement(`canvas`);band.width=w;band.height=h;const b=band.getContext(`2d`);const free=()=>{canvas.width=canvas.height=band.width=band.height=0};if(!b){free();return``}const round=sticker.shape===`circle`;const count=2+Math.floor(rnd()*3);for(let i=0;i<count;i++){let x0;let y0;if(round){const phi=rnd()*Math.PI*2;x0=w/2+Math.cos(phi)*w/2;y0=h/2+Math.sin(phi)*h/2}else{const side=Math.floor(rnd()*4);const along=.1+rnd()*.8;x0=side===0?0:side===1?w:along*w;y0=side===2?0:side===3?h:along*h}const toward=Math.atan2(h/2-y0,w/2-x0)+(rnd()-.5)*1.5;const dx=Math.cos(toward);const dy=Math.sin(toward);const length=big*(.32+rnd()*.36);const deep=big*(.08+rnd()*.06);const soft=deep*(.62+rnd()*.2);const peak=.13+rnd()*.07;const bend=(rnd()<.5?-1:1)*big*(2.5+rnd()*4);const inner=rnd()<.5;const cx=x0-dy*bend;const cy=y0+dx*bend;const R=Math.abs(bend);const r0=R-(inner?deep:soft);const r1=R+(inner?soft:deep);const fold=b.createRadialGradient(cx,cy,r0,cx,cy,r1);const n=20;for(let s=0;s<=n;s++){const r=r0+(r1-r0)*s/n;const off=r-R;const shadeSide=inner?off<0:off>0;const u=Math.abs(off)/(shadeSide?deep:soft);fold.addColorStop(s/n,ink(peak*ease(u)))}b.setTransform(1,0,0,1,0,0);b.globalCompositeOperation=`source-over`;b.clearRect(0,0,w,h);b.fillStyle=fold;b.fillRect(0,0,w,h);const across=(deep+soft)*2.8;const back=length*.08;b.globalCompositeOperation=`destination-in`;b.setTransform(dx,dy,-dy*(across/length),dx*(across/length),x0-dx*back,y0-dy*back);const fade=b.createRadialGradient(0,0,0,0,0,length);for(let s=0;s<=12;s++)fade.addColorStop(s/12,`rgba(0, 0, 0, ${ease((s/12-.05)/.95).toFixed(4)})`);b.fillStyle=fade;b.fillRect(-big*4,-big*4*length/across,big*8,big*8*length/across);b.setTransform(1,0,0,1,0,0);b.globalCompositeOperation=`source-over`;g.drawImage(band,0,0)}const art=canvas.toDataURL(`image/png`);free();creases.set(sticker.id,art);return art}};
;

// ---- pages/sun-menu/cover-stickers.js ----
window.EyeParts=window.EyeParts||{};window.EyeParts.addSunCoverStickers=function addSunCoverStickers(ed,sun){Object.assign(sun,{makeGroup,placeGroup,drawStickers});function stickerEl(sticker,src,creased){const el=document.createElement(`div`);el.className=`nb-sticker is-${sticker.shape}`;const face=document.createElement(`div`);face.className=`nb-sticker-face`;const img=document.createElement(`img`);img.alt=``;img.draggable=false;img.src=src;face.appendChild(img);if(creased){const art=sun.creaseArt(sticker);if(art){const lines=document.createElement(`img`);lines.className=`nb-sticker-creases`;lines.alt=``;lines.draggable=false;lines.src=art;face.appendChild(lines)}}el.appendChild(face);sun.placeOnCover(el,sticker);return el}function makeGroup(sticker,src,creased){const root=document.createElement(`div`);root.className=`nb-sticker-set`;const body=document.createElement(`div`);body.className=`nb-sticker-body`;const main=stickerEl(sticker,src,creased);body.appendChild(main);root.appendChild(body);return{sticker,src,creased,root,body,main,bends:{},wraps:{}}}function makeBend(group,edge){const bend=document.createElement(`div`);bend.className=`nb-bend is-${edge}`;const inner=document.createElement(`div`);inner.className=`nb-cover-copy`;const copy=stickerEl(group.sticker,group.src,group.creased);const shade=document.createElement(`i`);shade.className=`nb-bend-shade is-${edge}`;copy.firstChild.appendChild(shade);inner.appendChild(copy);bend.appendChild(inner);group.root.appendChild(bend);return group.bends[edge]={bend,inner,copy,shade}}function makeWrap(group,edge){const inner=document.createElement(`div`);inner.className=`nb-cover-copy`;const copy=stickerEl(group.sticker,group.src,group.creased);inner.appendChild(copy);wrapStrip(edge).appendChild(inner);return group.wraps[edge]={inner,copy}}const wrapsEl=document.getElementById(`bookWraps`);wrapsEl.innerHTML=sun.EDGES.map(edge=>`<div class="nb-wrap is-${edge}"><div class="nb-wrap-in"></div></div>`).join(``);const wrapStrip=edge=>wrapsEl.querySelector(`.nb-wrap.is-${edge} .nb-wrap-in`);function placeGroup(group){const s=group.sticker;const{w,h}=sun.bookSize();if(w<2||h<2)return;const halfW=s.size*w/2+sun.RING*w;const halfH=s.size*w/sun.stickerRatio(s)/2+sun.RING*w;const over={left:halfW-s.x*w,right:s.x*w+halfW-w,top:halfH-s.y*h,bottom:s.y*h+halfH-h};const band=sun.BEND*w;sun.placeOnCover(group.main,s);group.body.style.clipPath=`inset(${over.top>0?band:0}px ${over.right>0?band:0}px ${over.bottom>0?band:0}px ${over.left>0?band:0}px)`;sun.EDGES.forEach(edge=>{const reached=over[edge]>0;if(!reached){if(group.bends[edge])group.bends[edge].bend.hidden=true;if(group.wraps[edge])group.wraps[edge].inner.hidden=true;return}const part=group.bends[edge]||makeBend(group,edge);const wrap=group.wraps[edge]||makeWrap(group,edge);part.bend.hidden=false;wrap.inner.hidden=false;sun.placeOnCover(part.copy,s);sun.placeOnCover(wrap.copy,s);const squeezed=Math.min(over[edge],band*.9);const scale=band/(band+squeezed);const line=edge===`left`?band:edge===`right`?w-band:edge===`top`?band:h-band;part.inner.style.transformOrigin=sun.isSideways(edge)?`${line}px 0`:`0 ${line}px`;part.inner.style.transform=sun.isSideways(edge)?`scaleX(${scale.toFixed(4)})`:`scaleY(${scale.toFixed(4)})`;const away=edge===`left`||edge===`top`?squeezed:-squeezed;wrap.inner.style.transform=sun.isSideways(edge)?`translateX(${away.toFixed(1)}px)`:`translateY(${away.toFixed(1)}px)`;const faceLeft=s.x*w-halfW;const faceTop=s.y*h-halfH;const span=band+squeezed;const st=part.shade.style;st.opacity=Math.min(1,over[edge]/(band*.9)).toFixed(3);st.width=sun.isSideways(edge)?`${span}px`:`100%`;st.height=sun.isSideways(edge)?`100%`:`${span}px`;st.left=edge===`left`?`${band-span-faceLeft}px`:edge===`right`?`${w-band-faceLeft}px`:`0`;st.top=edge===`top`?`${band-span-faceTop}px`:edge===`bottom`?`${h-band-faceTop}px`:`0`})}function drawStickers(){wrapsEl.querySelectorAll(`.nb-wrap-in`).forEach(el=>el.replaceChildren());sun.groups=ed.state.presentation.stickers.filter(s=>sun.photos.has(s.id)).map(s=>makeGroup(s,sun.photos.get(s.id),true));if(sun.placing){sun.placing.group=makeGroup(sun.placing.sticker,sun.placing.src,false);sun.groups.push(sun.placing.group)}sun.layer.replaceChildren(...sun.groups.map(group=>group.root));sun.groups.forEach(placeGroup)}ed.relayStickers=()=>sun.groups.forEach(placeGroup);ed.refreshStickers=()=>{const stickers=ed.state.presentation.stickers;return ed.idbGetManyImages(stickers.map(s=>ed.stickerKey(s.id))).then(found=>{sun.photos.clear();stickers.forEach(s=>{const images=found.get(ed.stickerKey(s.id));if(images&&images[0])sun.photos.set(s.id,images[0].src)});drawStickers()}).catch(()=>{})}};
;

